/** * 主界面底部导航项（基于 Figma 设计） * Bottom navigation items for home screen (Based on Figma design) */ sealed class HomeDestination( val route: String, val icon: ImageVector, val labelResId: Int ) { data object Chats : HomeDestination( route = "chats", icon = Icons.AutoMirrored.Filled.Chat, labelResId = R.string.nav_chats )
data object Contacts : HomeDestination( route = "contacts", icon = Icons.Filled.People, labelResId = R.string.nav_contacts )
data object Me : HomeDestination( route = "me", icon = Icons.Filled.Person, labelResId = R.string.nav_me ) }
// 在外部定义 items 列表，避免类初始化问题 private val homeDestinationItems: List<HomeDestination> get() = listOf( HomeDestination.Chats, HomeDestination.Contacts, HomeDestination.Me )
/** * 主界面组合项（基于 Figma 设计） * Home screen composable (Based on Figma design) * * @param onLogout 登出回调 / Logout callback * @param modifier 修饰符 / Modifier */ @OptIn(ExperimentalMaterial3Api::class) @Composable fun HomeScreen( onLogout: () -> Unit, modifier: Modifier = Modifier ) { val items = homeDestinationItems val navController = rememberNavController() val navBackStackEntry by navController.currentBackStackEntryAsState() val currentDestination = navBackStackEntry?.destination val currentRoute = currentDestination?.route val isFullScreenRoute = currentRoute?.let { it.startsWith("chat_detail") || it == LANGUAGE_SETTINGS_ROUTE || it == PRIVACY_SETTINGS_ROUTE || it == ABOUT_ROUTE || it == PROFILE_EDIT_ROUTE || it.startsWith(USER_PROFILE_ROUTE) || it.startsWith(GROUP_PROFILE_ROUTE) || it.startsWith(CHAT_SEARCH_ROUTE) || it.startsWith(GROUP_MEMBER_SEARCH_ROUTE) || it.startsWith(MEMBER_MESSAGE_SEARCH_ROUTE) || it.startsWith(MESSAGE_FILTER_SEARCH_ROUTE) } == true val surfaceColor = MaterialTheme.colorScheme.surface
// 创建共享的 HomeViewModel（用于添加好友等全局功能） val sharedHomeViewModel: HomeViewModel = hiltViewModel()
// ========== 固定布局：顶栏 + 内容 + 底栏 ========== Scaffold( topBar = { // ========== 固定顶栏（所有页面共用，包括 chat_detail） ========== Surface( color = Color.Transparent ) { Box( modifier = Modifier .fillMaxWidth() .background( brush = Brush.verticalGradient( colors = listOf(PrimaryBlue, LightBlue) ) ) .statusBarsPadding() .padding(horizontal = 4.dp, vertical = 8.dp) ) { // 顶栏内容平滑切换 AnimatedContent( targetState = currentRoute, transitionSpec = { fadeIn(animationSpec = tween(150)) togetherWith fadeOut(animationSpec = tween(150)) }, label = "TopBarContent" ) { route -> when { route?.startsWith("chat_detail") == true -> { // 使用 ChatDetailViewModel 来获取正确的头像 val chatDetailViewModel: ChatDetailViewModel = hiltViewModel(navBackStackEntry!!) val otherUserId by chatDetailViewModel.otherUserId.collectAsStateWithLifecycle() val otherUserAvatarUrl by chatDetailViewModel.otherUserAvatarUrl.collectAsStateWithLifecycle() val conversationType by chatDetailViewModel.conversationType.collectAsStateWithLifecycle() val convoId by chatDetailViewModel.conversationId.collectAsStateWithLifecycle() val conversationNameVm by chatDetailViewModel.conversationName.collectAsStateWithLifecycle() val conversationAvatarVm by chatDetailViewModel.conversationAvatarUrl.collectAsStateWithLifecycle()
// 从路由参数获取对话名称 val conversationNameArg = navBackStackEntry?.arguments?.getString("conversationName")?.let { URLDecoder.decode(it, StandardCharsets.UTF_8.toString()) } ?: ""
// 从路由参数获取初始头像（作为 fallback） val fallbackAvatarArg = navBackStackEntry?.arguments?.getString("conversationAvatar")?.let { URLDecoder.decode(it, StandardCharsets.UTF_8.toString()) } ?: ""
val resolvedConversationName = conversationNameVm.ifBlank { conversationNameArg } val resolvedConversationAvatar = when { otherUserAvatarUrl.isNotBlank() -> otherUserAvatarUrl conversationAvatarVm.isNotBlank() -> conversationAvatarVm else -> fallbackAvatarArg }
ChatDetailTopBar( conversationName = resolvedConversationName, // 优先使用 ViewModel 中解析好的头像 URL，如果为空则使用路由参数 conversationAvatar = resolvedConversationAvatar, onBack = { navController.popBackStack() }, onProfileClick = { when (conversationType) { ConversationType.PRIVATE -> if (otherUserId.isNotBlank()) { navController.navigate("$USER_PROFILE_ROUTE/$otherUserId?conversationId=$convoId&source=chat") }
ConversationType.GROUP -> if (convoId.isNotBlank()) { navController.navigate("$GROUP_PROFILE_ROUTE/$convoId?source=chat") } } } ) }
route == LANGUAGE_SETTINGS_ROUTE -> { LanguageSettingsTopBar(onBack = { navController.popBackStack() }) }
route == PRIVACY_SETTINGS_ROUTE -> { PrivacySettingsTopBar(onBack = { navController.popBackStack() }) }
route == ABOUT_ROUTE -> { AboutTopBar(onBack = { navController.popBackStack() }) }
route == PROFILE_EDIT_ROUTE -> { ProfileHeaderTopBar(onBack = { navController.popBackStack() }) }
route?.startsWith(USER_PROFILE_ROUTE) == true -> { ProfileHeaderTopBar(onBack = { navController.popBackStack() }) }
route?.startsWith(GROUP_PROFILE_ROUTE) == true -> { val groupProfileViewModel: com.example.cs501_micro_chat.ui.profile.GroupProfileViewModel = hiltViewModel(navBackStackEntry!!) val groupState by groupProfileViewModel.uiState.collectAsStateWithLifecycle() GroupHeaderTopBar( memberCount = groupState.members.size, onBack = { navController.popBackStack() } ) }
route?.startsWith(GROUP_MEMBER_SEARCH_ROUTE) == true || route?.startsWith(MEMBER_MESSAGE_SEARCH_ROUTE) == true -> { GroupMemberSearchTopBar(onBack = { navController.popBackStack() }) }
route?.startsWith(MESSAGE_FILTER_SEARCH_ROUTE) == true -> { val filterArg = navBackStackEntry?.arguments?.getString("filter") val filter = MessageSearchFilter.fromArg(filterArg) MessageFilterSearchTopBar( title = stringResource(filter.titleRes), onBack = { navController.popBackStack() } ) }
route?.startsWith(CHAT_SEARCH_ROUTE) == true -> { ChatSearchTopBar(onBack = { navController.popBackStack() }) }
else -> { HomeTopBar( currentRoute = route, homeViewModel = sharedHomeViewModel, onNavigateToChat = { convoId, name, avatar -> val encodedName = URLEncoder.encode(name, StandardCharsets.UTF_8.toString()) val encodedAvatar = URLEncoder.encode(avatar, StandardCharsets.UTF_8.toString()) navController.navigate("chat_detail/$convoId/$encodedName/$encodedAvatar") { popUpTo(navController.graph.findStartDestination().id) { saveState = true } launchSingleTop = true restoreState = true } } ) } } } } } }, bottomBar = { // ========== 固定底栏（非全屏路由时显示） ========== if (!isFullScreenRoute) { NavigationBar( containerColor = surfaceColor, tonalElevation = 8.dp ) { items.forEach { destination -> NavigationBarItem( icon = { Icon( imageVector = destination.icon, contentDescription = stringResource(destination.labelResId), modifier = Modifier.size(24.dp) ) }, label = { Text( text = stringResource(destination.labelResId), fontSize = 12.sp ) }, selected = currentRoute == destination.route, onClick = { navController.navigate(destination.route) { popUpTo(navController.graph.findStartDestination().id) { saveState = true } launchSingleTop = true restoreState = true } }, colors = NavigationBarItemDefaults.colors( selectedIconColor = PrimaryBlue, selectedTextColor = PrimaryBlue, unselectedIconColor = secondaryTextColor(), unselectedTextColor = secondaryTextColor(), indicatorColor = PrimaryBlue.copy(alpha = 0.12f) ) ) } } } } ) { paddingValues -> // ========== 内容区域（NavHost） ========== NavHost( navController = navController, startDestination = HomeDestination.Chats.route, modifier = Modifier.padding(paddingValues) ) { composable(HomeDestination.Chats.route) { val homeViewModel: HomeViewModel = hiltViewModel() ChatListScreen( viewModel = homeViewModel, onChatClick = { conversation -> val displayName = homeViewModel.getDisplayName(conversation) val avatarUrl = homeViewModel.getAvatarUrl(conversation) val encodedName = URLEncoder.encode(displayName, StandardCharsets.UTF_8.toString()) val encodedAvatar = URLEncoder.encode(avatarUrl, StandardCharsets.UTF_8.toString()) navController.navigate( "chat_detail/${conversation.id}/$encodedName/$encodedAvatar" ) } ) }
composable(HomeDestination.Contacts.route) { backStackEntry -> val contactsViewModel: ContactsViewModel = hiltViewModel() val refreshFlow = remember(backStackEntry) { backStackEntry.savedStateHandle.getStateFlow("contacts_refresh", false) } val refreshRequested by refreshFlow.collectAsStateWithLifecycle()
LaunchedEffect(refreshRequested) { if (refreshRequested) { contactsViewModel.refresh() backStackEntry.savedStateHandle["contacts_refresh"] = false } } ContactsScreen( viewModel = contactsViewModel, onContactClick = { contact -> if (contact.isGroup() && contact.conversationId.isNotBlank()) { navController.navigate("$GROUP_PROFILE_ROUTE/${contact.conversationId}?source=contacts") } else if (!contact.isGroup() && contact.contactId.isNotBlank()) { navController.navigate("$USER_PROFILE_ROUTE/${contact.contactId}?conversationId=${contact.conversationId}&source=contacts") } }, onAvatarClick = { contact -> if (contact.isGroup() && contact.conversationId.isNotBlank()) { navController.navigate("$GROUP_PROFILE_ROUTE/${contact.conversationId}?source=contacts") } else if (!contact.isGroup() && contact.contactId.isNotBlank()) { navController.navigate("$USER_PROFILE_ROUTE/${contact.contactId}?conversationId=${contact.conversationId}&source=contacts") } } ) }
composable(HomeDestination.Me.route) { backStackEntry -> val themeViewModel: ThemeViewModel = hiltViewModel() val themeOption by themeViewModel.themeOption.collectAsStateWithLifecycle() val profileViewModel: ProfileSettingsViewModel = hiltViewModel() val profileState by profileViewModel.uiState.collectAsStateWithLifecycle() val context = LocalContext.current val savedStateHandle = backStackEntry.savedStateHandle val profileUpdatedFlow = remember(savedStateHandle) { savedStateHandle.getStateFlow(PROFILE_UPDATED_KEY, false) } val profileUpdated by profileUpdatedFlow.collectAsStateWithLifecycle()
LaunchedEffect(profileUpdated) { if (profileUpdated) { profileViewModel.refreshProfile() savedStateHandle[PROFILE_UPDATED_KEY] = false } }
