ort androidx.compose.material3.BottomSheetDefaults import androidx.compose.material3.Checkbox import androidx.compose.material3.FilterChipDefaults import androidx.compose.material3.HorizontalDivider import androidx.compose.material3.ModalBottomSheet import androidx.compose.material3.OutlinedButton import androidx.compose.material3.TextButton import androidx.compose.material3.TextField import androidx.compose.material3.TextFieldDefaults import androidx.compose.material3.rememberModalBottomSheetState import androidx.compose.material3.* import androidx.compose.runtime.* import androidx.compose.runtime.rememberCoroutineScope import androidx.compose.runtime.saveable.rememberSaveable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.draw.clip import androidx.compose.ui.draw.shadow import androidx.compose.ui.graphics.Brush import androidx.compose.ui.graphics.Color import androidx.compose.ui.graphics.luminance import androidx.compose.ui.graphics.vector.ImageVector import androidx.compose.ui.layout.ContentScale import androidx.compose.ui.platform.LocalConfiguration import androidx.compose.ui.platform.LocalContext import androidx.compose.ui.res.stringResource import androidx.compose.ui.text.font.FontWeight import androidx.compose.ui.text.style.TextOverflow import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import androidx.compose.ui.window.Dialog import androidx.compose.ui.window.DialogProperties import androidx.core.content.ContextCompat import androidx.hilt.navigation.compose.hiltViewModel import androidx.lifecycle.compose.collectAsStateWithLifecycle import androidx.navigation.NavGraph.Companion.findStartDestination import androidx.navigation.NavType import androidx.navigation.compose.NavHost import androidx.navigation.compose.composable import androidx.navigation.compose.currentBackStackEntryAsState import androidx.navigation.compose.rememberNavController import androidx.navigation.navArgument import coil.compose.AsyncImage import com.example.cs501_micro_chat.R import com.example.cs501_micro_chat.data.model.Contact import com.example.cs501_micro_chat.data.model.Conversation import com.example.cs501_micro_chat.data.model.ConversationType import com.example.cs501_micro_chat.data.model.Message import com.example.cs501_micro_chat.data.model.MessageType import com.example.cs501_micro_chat.ui.chat.ChatDetailViewModel import com.example.cs501_micro_chat.ui.auth.LanguageOption import com.example.cs501_micro_chat.ui.chat.TranslationLanguageChooser import com.example.cs501_micro_chat.ui.chat.messageKey import com.example.cs501_micro_chat.ui.profile.GroupProfileScreen import com.example.cs501_micro_chat.ui.profile.UserProfileScreen import com.example.cs501_micro_chat.ui.search.ChatSearchScreen import com.example.cs501_micro_chat.ui.search.GroupMemberSearchScreen import com.example.cs501_micro_chat.ui.search.MessageFilterSearchScreen import com.example.cs501_micro_chat.ui.search.MessageSearchFilter import com.example.cs501_micro_chat.ui.search.MemberMessageSearchScreen import com.example.cs501_micro_chat.ui.settings.AboutScreen import com.example.cs501_micro_chat.ui.settings.PrivacySettingsScreen import com.example.cs501_micro_chat.ui.settings.ProfileEditScreen import com.example.cs501_micro_chat.ui.settings.SettingsScreen import com.example.cs501_micro_chat.ui.theme.ThemeOption import com.example.cs501_micro_chat.ui.theme.ThemeViewModel import java.io.File import java.net.URLDecoder import java.net.URLEncoder import java.nio.charset.StandardCharsets import java.text.Collator import java.time.Instant import java.time.LocalDate import java.time.ZoneId import java.time.format.DateTimeFormatter import java.util.Locale import kotlinx.coroutines.Dispatchers import kotlinx.coroutines.launch import kotlinx.coroutines.withContext import android.widget.Toast
// Figma Design Colors (still used for branding) private val PrimaryBlue = Color(0xFF3296FA) private val LightBlue = Color(0xFF66B3FF) private val UnreadBadgeRed = Color(0xFFEF4444)
// Helper functions for text colors (supports Dark Mode) @Composable private fun primaryTextColor() = MaterialTheme.colorScheme.onSurface
@Composable private fun secondaryTextColor() = MaterialTheme.colorScheme.onSurfaceVariant private const val LANGUAGE_SETTINGS_ROUTE = "language_settings" private const val PRIVACY_SETTINGS_ROUTE = "privacy_settings" private const val ABOUT_ROUTE = "about" private const val PROFILE_EDIT_ROUTE = "profile_edit" private const val USER_PROFILE_ROUTE = "user_profile" private const val GROUP_PROFILE_ROUTE = "group_profile" private const val CHAT_SEARCH_ROUTE = "chat_search" private const val GROUP_MEMBER_SEARCH_ROUTE = "group_member_search" private const val MEMBER_MESSAGE_SEARCH_ROUTE = "member_message_search" private const val MESSAGE_FILTER_SEARCH_ROUTE = "message_filter_search" private const val PROFILE_UPDATED_KEY = "profile_updated"
/** * 主界面底部导航项（基于 Figma 设计） * Bottom navigation items for home screen (Based on Figma design) */ sealed class HomeDestination( val route: String, val icon: ImageVector, val labelResId: Int ) { data object Chats : HomeDestination( route = "chats", icon = Icons.AutoMirrored.Filled.Chat, labelResId = R.string.nav_chats )
data object Contacts : HomeDestination( route = "contacts", icon = Icons.Filled.People, labelResId = R.string.nav_contacts )
data object Me : HomeDestination( route = "me", icon = Icons.Filled.Person, labelResId = R.string.nav_me ) }
// 在外部定义 items 列表，避免类初始化问题 private val homeDestinationItems: List<HomeDestination> get() = listOf( HomeDestination.Chats, HomeDestination.Contacts, HomeDestination.Me )
/** * 主界面组合项（基于 Figma 设计） * Home screen composable (Based on Figma design) * * @param onLogout 登出回调 / Logout callback * @param modifier 修饰符 / Modifier */ @OptIn(ExperimentalMaterial3Api::class) @Composable fun HomeScreen( onLogout: () -> Unit, modifier: Modifier = Modifier ) { val items = homeDestinationItems val navController = rememberNavController() val navBackStackEntry by navController.currentBackStackEntryAsState() val currentDestination = navBackStackEntry?.destination val currentRoute = currentDestination?.route val isFullScreenRoute = currentRoute?.let { it.startsWith("chat_detail") || it == LANGUAGE_SETTINGS_ROUTE || it == PRIVACY_SETTINGS_ROUTE || it == ABOUT_ROUTE || it == PROFILE_EDIT_ROUTE || it.startsWith(USER_PROFILE_ROUTE) || it.startsWith(GROUP_PROFILE_ROUTE) || it.startsWith(CHAT_SEARCH_ROUTE) || it.startsWith(GROUP_MEMBER_SEARCH_ROUTE) || it.startsWith(MEMBER_MESSAGE_SEARCH_ROUTE) || it.startsWith(MESSAGE_FILTER_SEARCH_ROUTE) } == true val surfaceColor = MaterialTheme.colorScheme.surface
// 创建共享的 HomeViewModel（用于添加好友等全局功能） val sharedHomeViewModel: HomeViewModel = hiltViewModel()
// ========== 固定布局：顶栏 + 内容 + 底栏 ========== Scaffold( topBar = { // ========== 固定顶栏（所有页面共用，包括 chat_detail） ========== Surface( color = Color.Transparent ) { Box( modifier = Modifier .fillMaxWidth() .background( brush = Brush.verticalGradient( colors = listOf(PrimaryBlue, LightBlue) ) ) .statusBarsPadding() .padding(horizontal = 4.dp, vertical = 8.dp) ) { // 顶栏内容平滑切换 AnimatedContent( targetState = currentRoute, transitionSpec = { fadeIn(animationSpec = tween(150)) togetherWith fadeOut(animationSpec = tween(150)) }, label = "TopBarContent" ) { route -> when { route?.startsWith("chat_detail") == true -> { // 使用 ChatDetailViewModel 来获取正确的头像 val chatDetailViewModel: ChatDetailViewModel = hiltViewModel(navBackStackEntry!!) val otherUserId by chatDetailViewModel.otherUserId.collectAsStateWithLifecycle() val otherUserAvatarUrl by chatDetailViewModel.otherUserAvatarUrl.collectAsStateWithLifecycle() val conversationType by chatDetailViewModel.conversationType.collectAsStateWithLifecycle() val convoId by chatDetailViewModel.conversationId.collectAsStateWithLifecycle() val conversationNameVm by chatDetailViewModel.conversationName.collectAsStateWithLifecycle() val conversationAvatarVm by chatDetailViewModel.conversationAvatarUrl.collectAsStateWithLifecycle()
// 从路由参数获取对话名称 val conversationNameArg = navBackStackEntry?.arguments?.getString("conversationName")?.let { URLDecoder.decode(it, StandardCharsets.UTF_8.toString()) } ?: ""
// 从路由参数获取初始头像（作为 fallback） val fallbackAvatarArg = navBackStackEntry?.arguments?.getString("conversationAvatar")?.let { URLDecoder.decode(it, StandardCharsets.UTF_8.toString()) } ?: ""
val resolvedConversationName = conversationNameVm.ifBlank { conversationNameArg } val resolvedConversationAvatar = when { otherUserAvatarUrl.isNotBlank() -> otherUserAvatarUrl conversationAvatarVm.isNotBlank() -> conversationAvatarVm else -> fallbackAvatarArg }
ChatDetailTopBar( conversationName = resolvedConversationName, // 优先使用 ViewModel 中解析好的头像 URL，如果为空则使用路由参数 conversationAvatar = resolvedConversationAvatar, onBack = { navController.popBackStack() }, onProfileClick = { when (conversationType) { ConversationType.PRIVATE -> if (otherUserId.isNotBlank()) { navController.navigate("$USER_PROFILE_ROUTE/$otherUserId?conversationId=$convoId&source=chat") }
ConversationType.GROUP -> if (convoId.isNotBlank()) { navController.navigate("$GROUP_PROFILE_ROUTE/$convoId?source=chat") } } } ) }
route == LANGUAGE_SETTINGS_ROUTE -> { LanguageSettingsTopBar(onBack = { navController.popBackStack() }) }
route == PRIVACY_SETTINGS_ROUTE -> { PrivacySettingsTopBar(onBack = { navController.popBackStack() }) }
route == ABOUT_ROUTE -> { AboutTopBar(onBack = { navController.popBackStack() }) }
route == PROFILE_EDIT_ROUTE -> { ProfileHeaderTopBar(onBack = { navController.popBackStack() }) }
route?.startsWith(USER_PROFILE_ROUTE) == true -> { ProfileHeaderTopBar(onBack = { navController.popBackStack() }) }
route?.startsWith(GROUP_PROFILE_ROUTE) == true -> { val groupProfileViewModel: com.example.cs501_micro_chat.ui.profile.GroupProfileViewModel = hiltViewModel(navBackStackEntry!!) val groupState by groupProfileViewModel.uiState.collectAsStateWithLifecycle() GroupHeaderTopBar( memberCount = groupState.members.size, onBack = { navController.popBackStack() } ) }
route?.startsWith(GROUP_MEMBER_SEARCH_ROUTE) == true || route?.startsWith(MEMBER_MESSAGE_SEARCH_ROUTE) == true -> { GroupMemberSearchTopBar(onBack = { navController.popBackStack() }) }
route?.startsWith(MESSAGE_FILTER_SEARCH_ROUTE) == true -> { val filterArg = navBackStackEntry?.arguments?.getString("filter") val filter = MessageSearchFilter.fromArg(filterArg) MessageFilterSearchTopBar( title = stringResource(filter.titleRes), onBack = { navController.popBackStack() } ) }
route?.startsWith(CHAT_SEARCH_ROUTE) == true -> { ChatSearchTopBar(onBack = { navController.popBackStack() }) }
else -> { HomeTopBar( currentRoute = route, homeViewModel = sharedHomeViewModel, onNavigateToChat = { convoId, name, avatar -> val encodedName = URLEncoder.encode(name, StandardCharsets.UTF_8.toString()) val encodedAvatar = URLEncoder.encode(avatar, StandardCharsets.UTF_8.toString()) navController.navigate("chat_detail/$convoId/$encodedName/$encodedAvatar") { popUpTo(navController.graph.findStartDestination().id) { saveState = true } launchSingleTop = true restoreState = true } } ) } } } } } }, bottomBar = { // ========== 固定底栏（非全屏路由时显示） ========== if (!isFullScreenRoute) { NavigationBar( containerColor = surfaceColor, tonalElevation = 8.dp ) { items.forEach { destination -> NavigationBarItem( icon = { Icon( imageVector = destination.icon, contentDescription = stringResource(destination.labelResId), modifier = Modifier.size(24.dp) ) }, label = { Text( text = stringResource(destination.labelResId), fontSize = 12.sp ) }, selected = currentRoute == destination.route, onClick = { navController.navigate(destination.route) { popUpTo(navController.graph.findStartDestination().id) { saveState = true } launchSingleTop = true restoreState = true } }, colors = NavigationBarItemDefaults.colors( selectedIconColor = PrimaryBlue, selectedTextColor = PrimaryBlue, unselectedIconColor = secondaryTextColor(), unselectedTextColor = secondaryTextColor(), indicatorColor = PrimaryBlue.copy(alpha = 0.12f) ) ) } } } } ) { paddingValues -> // ========== 内容区域（NavHost） ========== NavHost( navController = navController, startDestination = HomeDestination.Chats.route, modifier = Modifier.padding(paddingValues) ) { composable(HomeDestination.Chats.route) { val homeViewModel: HomeViewModel = hiltViewModel() ChatListScreen( viewModel = homeViewModel, onChatClick = { conversation -> val displayName = homeViewModel.getDisplayName(conversation) val avatarUrl = homeViewModel.getAvatarUrl(conversation) val encodedName = URLEncoder.encode(displayName, StandardCharsets.UTF_8.toString()) val encodedAvatar = URLEncoder.encode(avatarUrl, StandardCharsets.UTF_8.toString()) navController.navigate( "chat_detail/${conversation.id}/$encodedName/$encodedAvatar" ) } ) }
composable(HomeDestination.Contacts.route) { backStackEntry -> val contactsViewModel: ContactsViewModel = hiltViewModel() val refreshFlow = remember(backStackEntry) { backStackEntry.savedStateHandle.getStateFlow("contacts_refresh", false) } val refreshRequested by refreshFlow.collectAsStateWithLifecycle()
LaunchedEffect(refreshRequested) { if (refreshRequested) { contactsViewModel.refresh() backStackEntry.savedStateHandle["contacts_refresh"] = false } } ContactsScreen( viewModel = contactsViewModel, onContactClick = { contact -> if (contact.isGroup() && contact.conversationId.isNotBlank()) { navController.navigate("$GROUP_PROFILE_ROUTE/${contact.conversationId}?source=contacts") } else if (!contact.isGroup() && contact.contactId.isNotBlank()) { navController.navigate("$USER_PROFILE_ROUTE/${contact.contactId}?conversationId=${contact.conversationId}&source=contacts") } }, onAvatarClick = { contact -> if (contact.isGroup() && contact.conversationId.isNotBlank()) { navController.navigate("$GROUP_PROFILE_ROUTE/${contact.conversationId}?source=contacts") } else if (!contact.isGroup() && contact.contactId.isNotBlank()) { navController.navigate("$USER_PROFILE_ROUTE/${contact.contactId}?conversationId=${contact.conversationId}&source=contacts") } } ) }
composable(HomeDestination.Me.route) { backStackEntry -> val themeViewModel: ThemeViewModel = hiltViewModel() val themeOption by themeViewModel.themeOption.collectAsStateWithLifecycle() val profileViewModel: ProfileSettingsViewModel = hiltViewModel() val profileState by profileViewModel.uiState.collectAsStateWithLifecycle() val context = LocalContext.current val savedStateHandle = backStackEntry.savedStateHandle val profileUpdatedFlow = remember(savedStateHandle) { savedStateHandle.getStateFlow(PROFILE_UPDATED_KEY, false) } val profileUpdated by profileUpdatedFlow.collectAsStateWithLifecycle()
LaunchedEffect(profileUpdated) { if (profileUpdated) { profileViewModel.refreshProfile() savedStateHandle[PROFILE_UPDATED_KEY] = false } }
ProfileScreen( onLogout = onLogout, onLanguageClick = { navController.navigate(LANGUAGE_SETTINGS_ROUTE) }, onPrivacyClick = { if (profileState.isGoogleSignIn) { Toast .makeText( context, context.getString(R.string.privacy_google_sign_in_blocked), Toast.LENGTH_SHORT ) .show() } else { navController.navigate(PRIVACY_SETTINGS_ROUTE) } }, onAboutClick = { navController.navigate(ABOUT_ROUTE) }, onProfileClick = { navController.navigate(PROFILE_EDIT_ROUTE) }, themeOption = themeOption, onThemeSelected = themeViewModel::selectTheme, profileState = profileState ) } composable(LANGUAGE_SETTINGS_ROUTE) { SettingsScreen() } composable(PRIVACY_SETTINGS_ROUTE) { PrivacySettingsScreen() } composable(ABOUT_ROUTE) { AboutScreen() } composable(PROFILE_EDIT_ROUTE) { ProfileEditScreen( onBack = { navController.popBackStack() }, onProfileSaved = { navController.previousBackStackEntry ?.savedStateHandle ?.set(PROFILE_UPDATED_KEY, true) navController.popBackStack() } ) }
// ChatDetail 页面 - 从右侧滑入 composable( route = "chat_detail/{conversationId}/{conversationName}/{conversationAvatar}?targetDate={targetDate}", arguments = listOf( navArgument("conversationId") { type = NavType.StringType }, navArgument("conversationName") { type = NavType.StringType }, navArgument("conversationAvatar") { type = NavType.StringType }, navArgument("targetDate") { type = NavType.LongType defaultValue = -1L } ), enterTransition = { slideInHorizontally( initialOffsetX = { fullWidth -> fullWidth }, animationSpec = tween(300) ) + fadeIn(animationSpec = tween(300)) }, exitTransition = { fadeOut(animationSpec = tween(300)) }, popEnterTransition = { fadeIn(animationSpec = tween(300)) }, popExitTransition = { slideOutHorizontally( targetOffsetX = { fullWidth -> fullWidth }, animationSpec = tween(300) ) + fadeOut(animationSpec = tween(300)) } ) { backStackEntry -> val conversationId = backStackEntry.arguments?.getString("conversationId") ?: "" val targetDate = backStackEntry.arguments?.getLong("targetDate")?.takeIf { it > 0 } ChatDetailContent( conversationId = conversationId, targetDateMillis = targetDate, onAvatarClick = { userId -> navController.navigate("$USER_PROFILE_ROUTE/$userId?conversationId=$conversationId&source=chat") } ) }
composable( route = "$GROUP_PROFILE_ROUTE/{conversationId}?source={source}", arguments = listOf( navArgument("conversationId") { type = NavType.StringType }, navArgument("source") { type = NavType.StringType defaultValue = "" } ) ) { backStackEntry -> val conversationId = backStackEntry.arguments?.getString("conversationId") ?: return@composable val sourceArg = backStackEntry.arguments?.getString("source").orEmpty() val onStartChatHandler: (String, String, String) -> Unit = if (sourceArg == "chat") { { _, _, _ -> navController.popBackStack() } } else { { convoId, name, avatar -> val encodedName = URLEncoder.encode(name, StandardCharsets.UTF_8.toString()) val encodedAvatar = URLEncoder.encode(avatar, StandardCharsets.UTF_8.toString()) navController.navigate("chat_detail/$convoId/$encodedName/$encodedAvatar") { popUpTo(navController.graph.findStartDestination().id) { saveState = true } launchSingleTop = true restoreState = true } } } GroupProfileScreen( conversationId = conversationId, onBack = { navController.popBackStack() }, onStartChat = onStartChatHandler, onLeftGroup = { navController.popBackStack() }, onOpenSearch = { convoId -> val encodedId = URLEncoder.encode(convoId, StandardCharsets.UTF_8.toString()) navController.navigate("$CHAT_SEARCH_ROUTE/$encodedId") }, onMemberClick = { userId -> navController.navigate("$USER_PROFILE_ROUTE/$userId") }, onRefreshContacts = { navController.previousBackStackEntry?.savedStateHandle?.set("contacts_refresh", true) } ) }
composable( route = "$USER_PROFILE_ROUTE/{userId}?conversationId={conversationId}&source={source}", arguments = listOf( navArgument("userId") { type = NavType.StringType }, navArgument("conversationId") { type = NavType.StringType defaultValue = "" }, navArgument("source") { type = NavType.StringType defaultValue = "" } ) ) { backStackEntry -> val userId = backStackEntry.arguments?.getString("userId") ?: return@composable val sourceArg = backStackEntry.arguments?.getString("source").orEmpty() val onBackHandler: () -> Unit = { val popped = navController.popBackStack() if (!popped && sourceArg == "contacts") { navController.navigate(HomeDestination.Contacts.route) { popUpTo(navController.graph.findStartDestination().id) { saveState = true } launchSingleTop = true restoreState = true } } } val startChatHandler: (String, String, String) -> Unit = { conversationId, name, avatarUrl -> if (sourceArg == "chat") { navController.popBackStack() } else { val encodedId = URLEncoder.encode(conversationId, StandardCharsets.UTF_8.toString()) val encodedName = URLEncoder.encode(name, StandardCharsets.UTF_8.toString()) val encodedAvatar = URLEncoder.encode(avatarUrl, StandardCharsets.UTF_8.toString()) navController.navigate("chat_detail/$encodedId/$encodedName/$encodedAvatar") { popUpTo(navController.graph.findStartDestination().id) { saveState = true } launchSingleTop = true restoreState = true } } } UserProfileScreen( userId = userId, onBack = onBackHandler, onStartChat = startChatHandler, onSearchHistory = { conversationId -> val encodedId = URLEncoder.encode(conversationId, StandardCharsets.UTF_8.toString()) navController.navigate("$CHAT_SEARCH_ROUTE/$encodedId") }, onDeleted = { navController.popBackStack() } ) }
