/** * HomeScreen 的顶栏内容 */ @Composable fun HomeTopBar( currentRoute: String?, homeViewModel: HomeViewModel, onNavigateToChat: (String, String, String) -> Unit ) { // 控制下拉菜单的显示状态 var showAddMenu by remember { mutableStateOf(false) } // 控制添加好友弹窗的显示状态 var showAddFriendDialog by remember { mutableStateOf(false) } var showCreateGroupDialog by remember { mutableStateOf(false) } var createGroupError by remember { mutableStateOf<String?>(null) } var groupName by remember { mutableStateOf("") } val coroutineScope = rememberCoroutineScope() val context = LocalContext.current val addFriendResults by homeViewModel.addFriendSearchResults.collectAsStateWithLifecycle() var groupSearchQuery by remember { mutableStateOf("") } val selectedMemberIds = remember { mutableStateOf(setOf<String>()) } var selectedAvatarUri by remember { mutableStateOf<Uri?>(null) }
val pickGroupAvatarLauncher = rememberLauncherForActivityResult( contract = ActivityResultContracts.PickVisualMedia() ) { uri -> selectedAvatarUri = uri }
Row( modifier = Modifier .fillMaxWidth() .height(56.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Spacer(modifier = Modifier.width(48.dp))
Text( text = when (currentRoute) { HomeDestination.Chats.route -> stringResource(R.string.nav_chats) HomeDestination.Contacts.route -> stringResource(R.string.nav_contacts) HomeDestination.Me.route -> stringResource(R.string.nav_me) else -> "" }, color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.SemiBold )
// Chats 和 Contacts 页面都显示加号按钮和下拉菜单 if (currentRoute == HomeDestination.Chats.route || currentRoute == HomeDestination.Contacts.route) { Box { IconButton(onClick = { showAddMenu = true }) { Icon( imageVector = Icons.Filled.Add, contentDescription = "Add", tint = Color.White ) }
// 下拉菜单 DropdownMenu( expanded = showAddMenu, onDismissRequest = { showAddMenu = false }, modifier = Modifier.background(MaterialTheme.colorScheme.surface) ) { // 新增联系人选项 DropdownMenuItem( text = { Row( verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.Start, modifier = Modifier.padding(vertical = 4.dp) ) { Icon( imageVector = Icons.Filled.PersonAdd, contentDescription = stringResource(R.string.content_description_add_friend), tint = primaryTextColor(), modifier = Modifier.size(22.dp) ) Spacer(modifier = Modifier.width(12.dp)) Text( text = stringResource(R.string.add_option_new_contact), color = primaryTextColor(), fontSize = 16.sp, fontWeight = FontWeight.Medium ) } }, onClick = { showAddMenu = false showAddFriendDialog = true } )
HorizontalDivider( thickness = 0.5.dp, color = MaterialTheme.colorScheme.outlineVariant )
// 新增群组选项 DropdownMenuItem( text = { Row( verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.Start, modifier = Modifier.padding(vertical = 4.dp) ) { Icon( imageVector = Icons.Filled.GroupAdd, contentDescription = "Create Group", tint = primaryTextColor(), modifier = Modifier.size(22.dp) ) Spacer(modifier = Modifier.width(12.dp)) Text( text = stringResource(R.string.add_option_new_group), color = primaryTextColor(), fontSize = 16.sp, fontWeight = FontWeight.Medium ) } }, onClick = { showAddMenu = false createGroupError = null groupName = "" showCreateGroupDialog = true } ) } } } else { Spacer(modifier = Modifier.width(48.dp)) } }
// 添加好友搜索弹窗 if (showAddFriendDialog) { AddFriendDialog( homeViewModel = homeViewModel, onDismiss = { showAddFriendDialog = false homeViewModel.clearAddFriendSearch() } ) }
if (showCreateGroupDialog) { AlertDialog( onDismissRequest = { showCreateGroupDialog = false }, title = { Text(stringResource(R.string.add_option_new_group)) }, text = { Column(verticalArrangement = Arrangement.spacedBy(12.dp)) { OutlinedTextField( value = groupName, onValueChange = { groupName = it }, label = { Text(stringResource(R.string.group_profile_name_label)) }, singleLine = true ) Row( horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically ) { Button(onClick = { pickGroupAvatarLauncher.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)) }) { Text(text = if (selectedAvatarUri != null) stringResource(R.string.profile_edit_choose_photo) else stringResource(R.string.profile_edit_choose_photo)) } if (selectedAvatarUri != null) { Text(text = context.getString(R.string.profile_edit_remove_avatar)) } } OutlinedTextField( value = groupSearchQuery, onValueChange = { groupSearchQuery = it homeViewModel.searchUsersForAddFriend(it) }, label = { Text(stringResource(R.string.add_friend_search_placeholder)) }, singleLine = true, leadingIcon = { Icon(imageVector = Icons.Default.Search, contentDescription = null) } ) if (groupSearchQuery.isNotBlank()) { val currentId = homeViewModel.currentUserId LazyColumn( modifier = Modifier .heightIn(max = 200.dp) ) { items(addFriendResults) { user -> if (user.id == currentId) return@items val checked = selectedMemberIds.value.contains(user.id) Row( modifier = Modifier .fillMaxWidth() .clickable { selectedMemberIds.value = if (checked) selectedMemberIds.value - user.id else selectedMemberIds.value + user.id } .padding(vertical = 8.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp) ) { Checkbox( checked = checked, onCheckedChange = { selectedMemberIds.value = if (it) selectedMemberIds.value + user.id else selectedMemberIds.value - user.id } ) Text(text = user.username.ifBlank { user.email.substringBefore("@") }) } } } Text( text = "${selectedMemberIds.value.size} selected", style = MaterialTheme.typography.bodySmall ) } createGroupError?.let { Text(text = it, color = MaterialTheme.colorScheme.error, fontSize = 13.sp) } } }, confirmButton = { TextButton( onClick = { val name = groupName.trim() if (name.isEmpty()) { createGroupError = context.getString(R.string.group_profile_name_label) return@TextButton } // 验证至少选择1个成员（加上群主共2人） if (selectedMemberIds.value.isEmpty()) { createGroupError = context.getString(R.string.group_create_min_members_error) return@TextButton } coroutineScope.launch { createGroupError = null var avatarBytes: ByteArray? = null var mimeType = "image/jpeg" var extension: String? = null selectedAvatarUri?.let { uri -> try { mimeType = context.contentResolver.getType(uri) ?: "image/jpeg" extension = MimeTypeMap.getSingleton() .getExtensionFromMimeType(mimeType) avatarBytes = withContext(Dispatchers.IO) { context.contentResolver.openInputStream(uri)?.use { it.readBytes() } } } catch (e: Exception) { createGroupError = e.message ?: "Failed to read image" return@launch } }
val result = homeViewModel.createGroup( name = name, memberIds = selectedMemberIds.value.toList(), avatarBytes = avatarBytes, avatarMimeType = mimeType, avatarExtension = extension ) result.onSuccess { groupId -> showCreateGroupDialog = false groupName = "" selectedMemberIds.value = emptySet() selectedAvatarUri = null onNavigateToChat(groupId, name, "") }.onFailure { error -> createGroupError = error.message ?: "Failed to create group" } } } ) { Text(text = stringResource(R.string.profile_edit_save)) } }, dismissButton = { TextButton(onClick = { showCreateGroupDialog = false }) { Text(text = stringResource(R.string.user_profile_delete_confirm_cancel)) } } ) }
}
