/** * ChatDetail 的内容区域（不包含顶栏） */ private sealed interface ChatListItem { data class DateHeader(val date: LocalDate) : ChatListItem data class MessageItem(val message: Message) : ChatListItem }
@OptIn(ExperimentalMaterial3Api::class) @Composable fun ChatDetailContent( conversationId: String, targetDateMillis: Long? = null, onAvatarClick: (String) -> Unit = {} ) { val viewModel: ChatDetailViewModel = hiltViewModel() val context = LocalContext.current
val messages by viewModel.messages.collectAsStateWithLifecycle() val isLoading by viewModel.isLoading.collectAsStateWithLifecycle() val hasLoadedInitial by viewModel.hasLoadedInitial.collectAsStateWithLifecycle() val currentUserId by viewModel.currentUserId.collectAsStateWithLifecycle() val translationStates by viewModel.translationStates.collectAsStateWithLifecycle() val voiceTranscriptionStates by viewModel.voiceTranscriptionStates.collectAsStateWithLifecycle() val summaryState by viewModel.summaryState.collectAsStateWithLifecycle() val preferredTranslationLanguage by viewModel.preferredTranslationLanguage.collectAsStateWithLifecycle()
var inputText by remember { mutableStateOf("") } var showActionSheet by remember { mutableStateOf(false) } var messageAwaitingTranslation by remember { mutableStateOf<Message?>(null) } var selectedLanguage by remember(preferredTranslationLanguage) { mutableStateOf(preferredTranslationLanguage) } var isSummarySelectionMode by remember { mutableStateOf(false) } var selectedSummaryMessages by remember { mutableStateOf(setOf<String>()) } var showSummaryDialog by remember { mutableStateOf(false) } val languageOptions = remember { LanguageOption.entries } var textToSpeech by remember { mutableStateOf<TextToSpeech?>(null) } var ttsReady by remember { mutableStateOf(false) } val actionSheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true) val coroutineScope = rememberCoroutineScope() val contentResolver = context.contentResolver var isRecording by remember { mutableStateOf(false) } var mediaRecorder by remember { mutableStateOf<MediaRecorder?>(null) } var recordingFile by remember { mutableStateOf<File?>(null) } var recordingStart by remember { mutableStateOf(0L) } val listState = rememberLazyListState()
LaunchedEffect(conversationId) { isSummarySelectionMode = false selectedSummaryMessages = emptySet() showSummaryDialog = false viewModel.clearSummaryResult() viewModel.loadMessages(conversationId) }
fun resolveMimeType(uri: Uri, fallback: String): Pair<String, String?> { val resolverType = contentResolver.getType(uri) val mimeType = resolverType ?: fallback val extension = MimeTypeMap.getSingleton() .getExtensionFromMimeType(mimeType) ?: uri.toString().substringAfterLast('.', "") return mimeType to extension }
fun handlePickedMedia(uri: Uri, isVideo: Boolean) { coroutineScope.launch { val (mimeType, extension) = resolveMimeType( uri, if (isVideo) "video/mp4" else "image/jpeg" ) val bytes = withContext(Dispatchers.IO) { contentResolver.openInputStream(uri)?.use { it.readBytes() } } ?: return@launch
if (isVideo) { viewModel.uploadVideoMessage( conversationId = conversationId, videoBytes = bytes, mimeType = mimeType, extension = extension ) } else { viewModel.uploadImageMessage( conversationId = conversationId, imageBytes = bytes, mimeType = mimeType, extension = extension ) } } }
fun startRecording() { try { val output = File(context.cacheDir, "voice_${System.currentTimeMillis()}.mp4") val recorder = MediaRecorder(context).apply { setAudioSource(MediaRecorder.AudioSource.MIC) setOutputFormat(MediaRecorder.OutputFormat.MPEG_4) setAudioEncoder(MediaRecorder.AudioEncoder.AAC) setAudioEncodingBitRate(128000) setAudioSamplingRate(44100) setOutputFile(output.absolutePath) prepare() start() } mediaRecorder = recorder recordingFile = output recordingStart = SystemClock.elapsedRealtime() isRecording = true } catch (e: Exception) { Log.e("ChatDetailContent", "Failed to start recording", e) mediaRecorder?.release() mediaRecorder = null recordingFile = null isRecording = false } }
fun stopRecordingAndUpload() { val file = recordingFile ?: return val start = recordingStart try { mediaRecorder?.apply { stop() release() } } catch (e: Exception) { Log.e("ChatDetailContent", "Failed to stop recording", e) } finally { mediaRecorder = null isRecording = false }
val duration = (SystemClock.elapsedRealtime() - start).coerceAtLeast(1L) coroutineScope.launch { val bytes = withContext(Dispatchers.IO) { runCatching { file.readBytes() }.getOrNull() } ?: return@launch withContext(Dispatchers.IO) { runCatching { file.delete() } } recordingFile = null viewModel.uploadVoiceMessage( conversationId = conversationId, audioBytes = bytes, durationMillis = duration, mimeType = "audio/mp4", extension = "mp4" ) } }
fun readDurationMillis(uri: Uri): Long? { // Try direct read via content resolver val direct = runCatching { val retriever = MediaMetadataRetriever() try { retriever.setDataSource(context, uri) retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)?.toLongOrNull() } finally { retriever.release() } }.getOrNull() if (direct != null) return direct
// Fallback: copy to temp file then read return runCatching { val temp = File.createTempFile("voice_meta_", ".tmp", context.cacheDir) context.contentResolver.openInputStream(uri)?.use { input -> temp.outputStream().use { output -> input.copyTo(output) } } ?: return null val retriever = MediaMetadataRetriever() try { retriever.setDataSource(temp.absolutePath) retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)?.toLongOrNull() } finally { retriever.release() temp.delete() } }.getOrNull() }
fun handlePickedFile(uri: Uri) { coroutineScope.launch { val (mimeType, extension) = resolveMimeType(uri, "application/octet-stream") val durationGuess = readDurationMillis(uri) ?: 1000L val bytes = withContext(Dispatchers.IO) { contentResolver.openInputStream(uri)?.use { it.readBytes() } } ?: return@launch
when { mimeType.contains("pdf") -> { viewModel.uploadVoiceMessage( conversationId = conversationId, audioBytes = bytes, durationMillis = durationGuess, mimeType = mimeType, extension = extension ) } mimeType.contains("audio") || mimeType.contains("mp4") -> { viewModel.uploadVoiceMessage( conversationId = conversationId, audioBytes = bytes, durationMillis = durationGuess, mimeType = mimeType, extension = extension ) } else -> { viewModel.uploadVoiceMessage( conversationId = conversationId, audioBytes = bytes, durationMillis = durationGuess, mimeType = mimeType, extension = extension ) } } } }
val audioPermissionLauncher = rememberLauncherForActivityResult( contract = ActivityResultContracts.RequestPermission() ) { granted -> if (granted) { startRecording() } }
fun requestAudioPermissionAndRecord() { when (ContextCompat.checkSelfPermission(context, Manifest.permission.RECORD_AUDIO)) { PackageManager.PERMISSION_GRANTED -> startRecording() else -> audioPermissionLauncher.launch(Manifest.permission.RECORD_AUDIO) } }
val photoPicker = rememberLauncherForActivityResult( contract = ActivityResultContracts.PickVisualMedia() ) { uri -> uri?.let { handlePickedMedia(it, isVideo = false) } } val videoPicker = rememberLauncherForActivityResult( contract = ActivityResultContracts.PickVisualMedia() ) { uri -> uri?.let { handlePickedMedia(it, isVideo = true) } } val filePicker = rememberLauncherForActivityResult( contract = ActivityResultContracts.GetContent() ) { uri -> uri?.let { handlePickedFile(it) } }
DisposableEffect(Unit) { val tts = TextToSpeech(context) { status -> ttsReady = status == TextToSpeech.SUCCESS } textToSpeech = tts
onDispose { tts.stop() tts.shutdown() textToSpeech = null ttsReady = false } }
fun speakMessage(text: String) { if (text.isBlank() || !ttsReady) return textToSpeech?.speak( text, TextToSpeech.QUEUE_FLUSH, null, "chat_message_tts_${text.hashCode()}" ) }
var hasJumpedToTarget by rememberSaveable { mutableStateOf(false) }
LaunchedEffect(messages.size, targetDateMillis) { if (messages.isNotEmpty()) { val targetIndex = targetDateMillis ?.takeIf { it > 0 } ?.let { ts -> messages.indexOfFirst { it.timestamp >= ts }.takeIf { it >= 0 } } ?: (messages.size - 1)
if (!hasJumpedToTarget || targetDateMillis != null) { listState.scrollToItem(targetIndex) hasJumpedToTarget = true } } }
LaunchedEffect(summaryState.result) { if (summaryState.result != null) { isSummarySelectionMode = false selectedSummaryMessages = emptySet() showSummaryDialog = true } }
LaunchedEffect(summaryState.error) { summaryState.error?.takeIf { it.isNotBlank() }?.let { Toast.makeText(context, it, Toast.LENGTH_SHORT).show() } }
fun startSummarySelection(initial: Message) { if (initial.type != MessageType.TEXT || summaryState.isSummarizing) return isSummarySelectionMode = true selectedSummaryMessages = setOf(messageKey(initial)) viewModel.clearSummaryResult() }
fun toggleSummarySelection(target: Message) { if (!isSummarySelectionMode || summaryState.isSummarizing || target.type != MessageType.TEXT) return val key = messageKey(target) selectedSummaryMessages = if (selectedSummaryMessages.contains(key)) { selectedSummaryMessages - key } else { selectedSummaryMessages + key } }
fun cancelSummarySelection() { if (summaryState.isSummarizing) return isSummarySelectionMode = false selectedSummaryMessages = emptySet() viewModel.clearSummaryResult() }
fun submitSummarySelection() { val selectedMessages = messages.filter { it.type == MessageType.TEXT && selectedSummaryMessages.contains(messageKey(it)) } if (selectedMessages.isEmpty()) { viewModel.clearSummaryResult() return } viewModel.summarizeMessages(selectedMessages) }
val backgroundColor = MaterialTheme.colorScheme.background val surfaceColorChat = MaterialTheme.colorScheme.surface val searchBackgroundChat = MaterialTheme.colorScheme.surfaceVariant val zoneId = remember { ZoneId.systemDefault() } if (showActionSheet) { ModalBottomSheet( onDismissRequest = { coroutineScope.launch { actionSheetState.hide() showActionSheet = false } }, sheetState = actionSheetState, containerColor = surfaceColorChat, dragHandle = { BottomSheetDefaults.DragHandle() } ) { data class SheetAction(val icon: ImageVector, val label: String, val onClick: () -> Unit) val actions = listOf( SheetAction( icon = Icons.Default.PhotoLibrary, label = stringResource(R.string.action_sheet_photos), onClick = { photoPicker.launch( PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly) ) } ), SheetAction( icon = Icons.Default.AttachFile, label = stringResource(R.string.action_sheet_file), onClick = { filePicker.launch("*/*") } ), SheetAction( icon = Icons.Default.Videocam, label = stringResource(R.string.action_sheet_video), onClick = { videoPicker.launch( PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.VideoOnly) ) } ), SheetAction( icon = Icons.Default.Mic, label = stringResource(R.string.action_sheet_voice), onClick = { if (isRecording) { stopRecordingAndUpload() } else { requestAudioPermissionAndRecord() } } ) )
