messageAwaitingTranslation?.let { pendingMessage -> AlertDialog( onDismissRequest = { messageAwaitingTranslation = null }, title = { Text(text = stringResource(R.string.translate_dialog_title)) }, text = { Column(verticalArrangement = Arrangement.spacedBy(8.dp)) { Text( text = stringResource(R.string.translate_dialog_subtitle), color = secondaryTextColor(), fontSize = 14.sp ) TranslationLanguageChooser( options = languageOptions, selected = selectedLanguage, onSelect = { selectedLanguage = it } ) } }, confirmButton = { TextButton( onClick = { viewModel.translateMessage(pendingMessage, selectedLanguage.displayName) messageAwaitingTranslation = null } ) { Text(text = stringResource(R.string.translate_dialog_confirm)) } }, dismissButton = { TextButton(onClick = { messageAwaitingTranslation = null }) { Text(text = stringResource(R.string.translate_dialog_cancel)) } } ) }
if (showSummaryDialog && summaryState.result != null) { AlertDialog( onDismissRequest = { showSummaryDialog = false viewModel.clearSummaryResult() }, title = { Text(text = stringResource(R.string.summary_dialog_title)) }, text = { Text( text = summaryState.result.orEmpty(), color = MaterialTheme.colorScheme.onSurface ) }, confirmButton = { TextButton( onClick = { showSummaryDialog = false viewModel.clearSummaryResult() } ) { Text(text = stringResource(R.string.summary_dialog_close)) } } ) } }
@Composable private fun SummarySelectionBar( selectedCount: Int, isSubmitting: Boolean, onCancel: () -> Unit, onSubmit: () -> Unit ) { Surface( modifier = Modifier.fillMaxWidth(), color = MaterialTheme.colorScheme.surface, tonalElevation = 3.dp, shadowElevation = 2.dp ) { Column( modifier = Modifier .fillMaxWidth() .padding(horizontal = 16.dp, vertical = 12.dp), verticalArrangement = Arrangement.spacedBy(8.dp) ) { Row( modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp) ) { Column(modifier = Modifier.weight(1f)) { Text( text = stringResource(R.string.summary_selection_title), fontWeight = FontWeight.SemiBold, fontSize = 15.sp ) Text( text = stringResource(R.string.summary_selection_subtitle, selectedCount), color = secondaryTextColor(), fontSize = 13.sp ) }
TextButton( onClick = onCancel, enabled = !isSubmitting ) { Text(text = stringResource(R.string.summary_selection_cancel)) } Button( onClick = onSubmit, enabled = selectedCount > 0 && !isSubmitting ) { if (isSubmitting) { CircularProgressIndicator( modifier = Modifier.size(16.dp), strokeWidth = 2.dp, color = Color.White ) } else { Icon( imageVector = Icons.Default.Summarize, contentDescription = null, modifier = Modifier.size(18.dp) ) Spacer(modifier = Modifier.width(6.dp)) } Text(text = stringResource(R.string.summary_selection_action)) } } if (isSubmitting) { LinearProgressIndicator( modifier = Modifier.fillMaxWidth(), color = PrimaryBlue ) } } } }
@Composable private fun DateDivider(date: LocalDate) { val configuration = LocalConfiguration.current val locale = if (configuration.locales.size() > 0) { configuration.locales[0] } else { Locale.getDefault() } val sameYearFormatter = remember(locale) { DateTimeFormatter.ofPattern("MMM d", locale) } val otherYearFormatter = remember(locale) { DateTimeFormatter.ofPattern("MMM d, yyyy", locale) } val today = LocalDate.now() val yesterday = today.minusDays(1) val label = when { date == today -> stringResource(R.string.chat_date_today) date == yesterday -> stringResource(R.string.chat_date_yesterday) date.year == today.year -> date.format(sameYearFormatter) else -> date.format(otherYearFormatter) } val lineColor = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.6f) Row( modifier = Modifier .fillMaxWidth() .padding(vertical = 4.dp), verticalAlignment = Alignment.CenterVertically ) { HorizontalDivider( modifier = Modifier.weight(1f), color = lineColor ) Text( text = label, modifier = Modifier.padding(horizontal = 12.dp), style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurfaceVariant ) HorizontalDivider( modifier = Modifier.weight(1f), color = lineColor ) } }
/** * 聊天列表页面（基于 Figma 设计）- 从 Firebase 读取真实数据 * Chat list screen (Based on Figma design) - Reads real data from Firebase */ @Composable fun ChatListScreen( viewModel: HomeViewModel = hiltViewModel(), onChatClick: (Conversation) -> Unit = {} ) { val conversations by viewModel.conversations.collectAsStateWithLifecycle() val isLoading by viewModel.isLoading.collectAsStateWithLifecycle() val isUsersLoading by viewModel.isUsersLoading.collectAsStateWithLifecycle() val areContactsReady by viewModel.isContactsReady.collectAsStateWithLifecycle()
// 搜索相关状态 val searchQuery by viewModel.searchQuery.collectAsStateWithLifecycle() val searchResults by viewModel.searchResults.collectAsStateWithLifecycle() val isSearching by viewModel.isSearching.collectAsStateWithLifecycle()
// 控制搜索框是否激活 var isSearchActive by remember { mutableStateOf(false) }
val backgroundColor = MaterialTheme.colorScheme.background val surfaceColor = MaterialTheme.colorScheme.surface val searchBarColor = MaterialTheme.colorScheme.surfaceVariant
val showLoading = isLoading || isUsersLoading || !areContactsReady
Box(modifier = Modifier.fillMaxSize()) { if (showLoading) { Box( modifier = Modifier .fillMaxSize() .background(backgroundColor), contentAlignment = Alignment.Center ) { CircularProgressIndicator(color = PrimaryBlue) } } else { Column( modifier = Modifier .fillMaxSize() .background(backgroundColor) ) { // 搜索栏 Surface( color = surfaceColor, shadowElevation = 2.dp ) { Column { if (isSearchActive) { // 激活状态：可编辑的搜索框 Row( modifier = Modifier .fillMaxWidth() .padding(16.dp) .clip(RoundedCornerShape(8.dp)) .background(searchBarColor) .padding(horizontal = 12.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically ) { Icon( imageVector = Icons.Filled.Search, contentDescription = stringResource(R.string.content_description_search), tint = secondaryTextColor(), modifier = Modifier.size(20.dp) ) Spacer(modifier = Modifier.width(8.dp)) TextField( value = searchQuery, onValueChange = { viewModel.updateSearchQuery(it) }, modifier = Modifier.weight(1f), placeholder = { Text( text = stringResource(R.string.search_hint), color = secondaryTextColor(), fontSize = 15.sp ) }, colors = TextFieldDefaults.colors( focusedContainerColor = Color.Transparent, unfocusedContainerColor = Color.Transparent, focusedIndicatorColor = Color.Transparent, unfocusedIndicatorColor = Color.Transparent ), maxLines = 4 ) } } else { // 默认状态：占位符搜索框 Row( modifier = Modifier .fillMaxWidth() .padding(16.dp) .clip(RoundedCornerShape(8.dp)) .background(searchBarColor) .clickable { isSearchActive = true } .padding(horizontal = 12.dp, vertical = 10.dp), verticalAlignment = Alignment.CenterVertically ) { Icon( imageVector = Icons.Filled.Search, contentDescription = stringResource(R.string.content_description_search), tint = secondaryTextColor(), modifier = Modifier.size(20.dp) ) Spacer(modifier = Modifier.width(8.dp)) Text( text = stringResource(R.string.search_hint), color = secondaryTextColor(), fontSize = 15.sp ) } } } }
// 显示搜索结果或对话列表 if (isSearchActive && searchQuery.isNotBlank()) { // 搜索结果 ConversationSearchResultsList( searchResults = searchResults, isSearching = isSearching, viewModel = viewModel, onChatClick = { conversation -> viewModel.clearSearch() isSearchActive = false onChatClick(conversation) } ) } else { // 正常对话列表 ConversationsList( conversations = conversations, isLoading = isLoading, viewModel = viewModel, onChatClick = onChatClick ) } } } } }
/** * 会话列表项（基于 Figma 设计）- 显示真实会话数据 * Conversation list item (Based on Figma design) - Displays real conversation data */ @Composable fun ConversationListItem( conversation: Conversation, viewModel: HomeViewModel, onClick: () -> Unit = {} ) { // 监听 userCache 的变化，确保用户信息加载后界面会更新 val userCache by viewModel.userCache.collectAsStateWithLifecycle()
val formattedTime = if (conversation.lastMessage.isNotBlank()) { viewModel.formatTime(conversation.lastMessageTime) } else { "" }
// 使用新的方法获取显示名称和头像 val displayName = viewModel.getDisplayName(conversation) val avatarUrl = viewModel.getAvatarUrl(conversation)
// 调试日志 Log.d("ConversationListItem", "Conversation ID: ${conversation.id}") Log.d("ConversationListItem", "Participants: ${conversation.participants}") Log.d("ConversationListItem", "Display Name: $displayName") Log.d("ConversationListItem", "Avatar URL: $avatarUrl") Log.d("ConversationListItem", "UserCache size: ${userCache.size}")
val rowBackground = MaterialTheme.colorScheme.surface Row( modifier = Modifier .fillMaxWidth() .clickable(onClick = onClick) .background(rowBackground) .padding(horizontal = 16.dp, vertical = 12.dp), verticalAlignment = Alignment.CenterVertically ) { // 头像 - 使用 Coil 加载网络图片 if (avatarUrl.isNotBlank()) { Log.d("ConversationListItem", "Loading image for $displayName: $avatarUrl") AsyncImage( model = avatarUrl, contentDescription = stringResource(R.string.content_description_avatar, displayName), modifier = Modifier .size(52.dp) .clip(CircleShape), contentScale = ContentScale.Crop, onError = { error -> Log.e("ConversationListItem", "Failed to load image for $displayName: ${error.result.throwable}") }, onSuccess = { Log.d("ConversationListItem", "Successfully loaded image for $displayName") } ) } else { // 没有头像URL时显示首字母 Log.d("ConversationListItem", "No avatarUrl for $displayName, showing initials") Box( modifier = Modifier .size(52.dp) .clip(CircleShape) .background(PrimaryBlue), contentAlignment = Alignment.Center ) { Text( text = displayName.firstOrNull()?.toString() ?: "?", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.Medium ) } }
Spacer(modifier = Modifier.width(12.dp))
// 会话信息 Column( modifier = Modifier.weight(1f) ) { Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Text( text = displayName, color = primaryTextColor(), fontSize = 16.sp, fontWeight = FontWeight.Medium, maxLines = 1, overflow = TextOverflow.Ellipsis, modifier = Modifier.weight(1f) ) if (formattedTime.isNotBlank()) { Text( text = formattedTime, color = secondaryTextColor(), fontSize = 12.sp ) } }
Spacer(modifier = Modifier.height(4.dp))
Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Text( text = formatLastMessagePreview(conversation.lastMessage), color = secondaryTextColor(), fontSize = 14.sp, maxLines = 1, overflow = TextOverflow.Ellipsis, modifier = Modifier.weight(1f) )
} } } }
@Composable private fun formatLastMessagePreview(lastMessage: String): String { val imageLabel = stringResource(R.string.last_message_image) val videoLabel = stringResource(R.string.last_message_video) val voiceSeconds = extractVoiceSeconds(lastMessage)
return when { lastMessage.equals("IMAGE", ignoreCase = true) || lastMessage.contains("图片") -> imageLabel lastMessage.equals("VIDEO", ignoreCase = true) || lastMessage.contains("视频") -> videoLabel lastMessage.startsWith("VOICE_", ignoreCase = true) -> { voiceSeconds?.let { stringResource(R.string.last_message_voice, it) } ?: stringResource(R.string.last_message_voice_no_duration) } lastMessage.contains("语音消息") || lastMessage.contains("voice", ignoreCase = true) -> { voiceSeconds?.let { stringResource(R.string.last_message_voice, it) } ?: stringResource(R.string.last_message_voice_no_duration) } else -> lastMessage } }
private fun extractVoiceSeconds(text: String): String? { val regex = Regex("(\\d+)\\s*s", RegexOption.IGNORE_CASE) regex.find(text)?.groupValues?.getOrNull(1)?.let { return it } val digits = text.filter { it.isDigit() } return digits.takeIf { it.isNotBlank() } }
/** * 对话搜索结果列表 * Conversation search results list */ @Composable fun ConversationSearchResultsList( searchResults: List<Conversation>, isSearching: Boolean, viewModel: HomeViewModel, onChatClick: (Conversation) -> Unit ) { val dividerColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.15f)
if (isSearching) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { CircularProgressIndicator(color = PrimaryBlue) } } else if (searchResults.isEmpty()) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { Column( horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp) ) { Icon( imageVector = Icons.Filled.SearchOff, contentDescription = null, tint = secondaryTextColor(), modifier = Modifier.size(64.dp) ) Text( text = stringResource(R.string.no_results_found), color = primaryTextColor(), fontSize = 16.sp, fontWeight = FontWeight.Medium ) Text( text = stringResource(R.string.try_different_search_keyword), color = secondaryTextColor(), fontSize = 14.sp ) } } } else { LazyColumn( modifier = Modifier.fillMaxSize() ) { item { Spacer(modifier = Modifier.height(8.dp)) Text( text = "${searchResults.size} result${if (searchResults.size > 1) "s" else ""} found", modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp), color = secondaryTextColor(), fontSize = 13.sp, fontWeight = FontWeight.Medium ) } items( items = searchResults, key = { it.id } ) { conversation -> ConversationListItem( conversation = conversation, viewModel = viewModel, onClick = { onChatClick(conversation) } ) HorizontalDivider( modifier = Modifier.padding(start = 72.dp), thickness = 0.5.dp, color = dividerColor ) } } } }
/** * 正常对话列表 * Normal conversations list */ @Composable fun ConversationsList( conversations: List<Conversation>, isLoading: Boolean, viewModel: HomeViewModel, onChatClick: (Conversation) -> Unit ) { val dividerColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.15f)
// 加载指示器 if (isLoading && conversations.isEmpty()) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { CircularProgressIndicator(color = PrimaryBlue) } } // 空状态 else if (conversations.isEmpty()) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { Column( horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp) ) { Icon( imageVector = Icons.AutoMirrored.Filled.Chat, contentDescription = null, tint = secondaryTextColor(), modifier = Modifier.size(64.dp) ) Text( text = stringResource(R.string.no_conversations_yet), color = secondaryTextColor(), fontSize = 16.sp ) Text( text = stringResource(R.string.start_new_chat_hint), color = secondaryTextColor(), fontSize = 14.sp ) } } } // 会话列表 else { LazyColumn( modifier = Modifier.fillMaxSize() ) { items( items = conversations, key = { it.id } ) { conversation -> ConversationListItem( conversation = conversation, viewModel = viewModel, onClick = { onChatClick(conversation) } ) HorizontalDivider( modifier = Modifier.padding(start = 72.dp), thickness = 0.5.dp, color = dividerColor ) } } } }
/** * 联系人页面（基于 Figma 设计）- 显示分组和联系人列表 * Contacts screen (Based on Figma design) - Shows groups and contacts list */ @Composable fun ContactsScreen( viewModel: ContactsViewModel = hiltViewModel(), homeViewModel: HomeViewModel = hiltViewModel(), onContactClick: (Contact) -> Unit = {}, onAvatarClick: (Contact) -> Unit = {} ) { val groups by viewModel.groups.collectAsStateWithLifecycle() val privateContacts by viewModel.privateContacts.collectAsStateWithLifecycle() val isLoading by viewModel.isLoading.collectAsStateWithLifecycle()
// 搜索相关状态 val searchQuery by viewModel.searchQuery.collectAsStateWithLifecycle() val searchResults by viewModel.searchResults.collectAsStateWithLifecycle() val isSearching by viewModel.isSearching.collectAsStateWithLifecycle()
// 待确认的好友请求 val pendingFriendRequests by homeViewModel.pendingFriendRequests.collectAsStateWithLifecycle()
val backgroundColor = MaterialTheme.colorScheme.background val surfaceColor = MaterialTheme.colorScheme.surface val searchBarColor = MaterialTheme.colorScheme.surfaceVariant
// 控制搜索框是否激活 var isSearchActive by remember { mutableStateOf(false) }
Box(modifier = Modifier.fillMaxSize()) { Column( modifier = Modifier .fillMaxSize() .background(backgroundColor) ) { // 搜索栏 Surface( color = surfaceColor, shadowElevation = 2.dp ) { Column { if (isSearchActive) { // 激活状态：可编辑的搜索框 Row( modifier = Modifier .fillMaxWidth() .padding(16.dp) .clip(RoundedCornerShape(8.dp)) .background(searchBarColor) .padding(horizontal = 12.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically ) { Icon( imageVector = Icons.Filled.Search, contentDescription = "Search", tint = secondaryTextColor(), modifier = Modifier.size(20.dp) ) Spacer(modifier = Modifier.width(8.dp)) TextField( value = searchQuery, onValueChange = { viewModel.updateSearchQuery(it) }, modifier = Modifier.weight(1f), placeholder = { Text( text = stringResource(R.string.contacts_search_hint), color = secondaryTextColor(), fontSize = 15.sp ) }, colors = TextFieldDefaults.colors( focusedContainerColor = Color.Transparent, unfocusedContainerColor = Color.Transparent, focusedIndicatorColor = Color.Transparent, unfocusedIndicatorColor = Color.Transparent ), maxLines = 4 ) } } else { // 默认状态：占位符搜索框 Row( modifier = Modifier .fillMaxWidth() .padding(16.dp) .clip(RoundedCornerShape(8.dp)) .background(searchBarColor) .clickable { isSearchActive = true } .padding(horizontal = 12.dp, vertical = 10.dp), verticalAlignment = Alignment.CenterVertically ) { Icon( imageVector = Icons.Filled.Search, contentDescription = stringResource(R.string.content_description_search), tint = secondaryTextColor(), modifier = Modifier.size(20.dp) ) Spacer(modifier = Modifier.width(8.dp)) Text( text = stringResource(R.string.contacts_search_hint), color = secondaryTextColor(), fontSize = 15.sp ) } } } }
// 显示搜索结果或联系人列表 if (isSearchActive && searchQuery.isNotBlank()) { // 搜索结果 SearchResultsList( searchResults = searchResults, isSearching = isSearching, viewModel = viewModel, onContactClick = { contact -> viewModel.clearSearch() isSearchActive = false onContactClick(contact) }, onAvatarClick = onAvatarClick ) } else { // 正常联系人列表 ContactsList( groups = groups, privateContacts = privateContacts, pendingFriendRequests = pendingFriendRequests, isLoading = isLoading, viewModel = viewModel, homeViewModel = homeViewModel, onContactClick = onContactClick, onAvatarClick = onAvatarClick ) } } } }
/** * 搜索结果列表 * Search results list */ @Composable fun SearchResultsList( searchResults: List<Contact>, isSearching: Boolean, viewModel: ContactsViewModel, onContactClick: (Contact) -> Unit, onAvatarClick: (Contact) -> Unit ) { val dividerColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.15f)
if (isSearching) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { CircularProgressIndicator(color = PrimaryBlue) } } else if (searchResults.isEmpty()) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { Column( horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp) ) { Icon( imageVector = Icons.Filled.SearchOff, contentDescription = null, tint = secondaryTextColor(), modifier = Modifier.size(64.dp) ) Text( text = stringResource(R.string.no_results_found), color = primaryTextColor(), fontSize = 16.sp, fontWeight = FontWeight.Medium ) Text( text = stringResource(R.string.try_different_search_keyword), color = secondaryTextColor(), fontSize = 14.sp ) } } } else { LazyColumn( modifier = Modifier.fillMaxSize() ) { item { Spacer(modifier = Modifier.height(8.dp)) Text( text = "${searchResults.size} result${if (searchResults.size > 1) "s" else ""} found", modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp), color = secondaryTextColor(), fontSize = 13.sp, fontWeight = FontWeight.Medium ) } items( items = searchResults, key = { it.contactId } ) { contact -> ContactListItem( contact = contact, viewModel = viewModel, onClick = { onContactClick(contact) }, onAvatarClick = onAvatarClick ) HorizontalDivider( modifier = Modifier.padding(start = 72.dp), thickness = 0.5.dp, color = dividerColor ) } } } }
/** * 正常联系人列表 * Normal contacts list */ @Composable fun ContactsList( groups: List<Contact>, privateContacts: List<Contact>, pendingFriendRequests: List<Contact>, isLoading: Boolean, viewModel: ContactsViewModel, homeViewModel: HomeViewModel, onContactClick: (Contact) -> Unit, onAvatarClick: (Contact) -> Unit ) { val dividerColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.15f) val collator = remember { Collator.getInstance(Locale.getDefault()).apply { strength = Collator.PRIMARY } }
// 对私聊联系人按字母排序 val sortedPrivateContacts = remember(privateContacts, collator) { privateContacts.sortedWith { a, b -> collator.compare(viewModel.getDisplayName(a), viewModel.getDisplayName(b)) } }
// 将私聊联系人按字母分组 val privateSections = remember(sortedPrivateContacts) { sortedPrivateContacts.groupBy { contact -> val name = viewModel.getDisplayName(contact).trim() val firstChar = name.firstOrNull()?.toString()?.uppercase(Locale.getDefault()) firstChar?.takeIf { it.length == 1 && it[0].isLetter() } ?: "#" }.toSortedMap() }
// 加载指示器 if (isLoading && groups.isEmpty() && privateContacts.isEmpty()) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { CircularProgressIndicator(color = PrimaryBlue) } } // 空状态 else if (groups.isEmpty() && privateContacts.isEmpty() && pendingFriendRequests.isEmpty()) { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { Column( horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp) ) { Icon( imageVector = Icons.Filled.People, contentDescription = null, modifier = Modifier.size(64.dp), tint = secondaryTextColor() ) Text( text = stringResource(R.string.no_contacts_yet), color = secondaryTextColor(), fontSize = 16.sp ) Text( text = stringResource(R.string.add_friends_to_start_chatting), color = secondaryTextColor(), fontSize = 14.sp ) } } } // 联系人列表 else { LazyColumn( modifier = Modifier.fillMaxSize() ) { // 待确认的好友请求（置顶） if (pendingFriendRequests.isNotEmpty()) { item(key = "pending_requests_header") { SectionHeader(title = stringResource(R.string.section_friend_requests)) } items( items = pendingFriendRequests, key = { "pending_${it.contactId}" } ) { contact -> PendingFriendRequestItem( contact = contact, onAccept = { homeViewModel.acceptFriendRequest(contact.contactId) }, onReject = { homeViewModel.rejectFriendRequest(contact.contactId) } ) HorizontalDivider( modifier = Modifier.padding(start = 72.dp), thickness = 0.5.dp, color = dividerColor ) } }
// 群组联系人 if (groups.isNotEmpty()) { item(key = "groups_header") { SectionHeader(title = stringResource(R.string.section_groups)) } items( items = groups, key = { "group_${it.contactId}" } ) { contact -> ContactListItem( contact = contact, viewModel = viewModel, onClick = { onContactClick(contact) }, onAvatarClick = onAvatarClick ) HorizontalDivider( modifier = Modifier.padding(start = 72.dp), thickness = 0.5.dp, color = dividerColor ) } }
// 私聊联系人（按字母分组） if (sortedPrivateContacts.isNotEmpty()) { item(key = "contacts_header") { SectionHeader(title = stringResource(R.string.section_contacts)) } privateSections.forEach { (letter, contactsInSection) -> item(key = "letter_$letter") { Text( text = letter, modifier = Modifier .fillMaxWidth() .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)) .padding(horizontal = 16.dp, vertical = 4.dp), color = PrimaryBlue, fontSize = 14.sp, fontWeight = FontWeight.Medium ) } items( items = contactsInSection, key = { "contact_${it.contactId}" } ) { contact -> ContactListItem( contact = contact, viewModel = viewModel, onClick = { onContactClick(contact) }, onAvatarClick = onAvatarClick ) HorizontalDivider( modifier = Modifier.padding(start = 72.dp), thickness = 0.5.dp, color = dividerColor ) } } } } } }
/** * 分组标题 * Section header for contacts list */ @Composable fun SectionHeader(title: String) { val sectionBackgroundColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
Surface( modifier = Modifier.fillMaxWidth(), color = sectionBackgroundColor ) { Text( text = title, modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp), color = secondaryTextColor(), fontSize = 13.sp, fontWeight = FontWeight.Medium ) } }
/** * 待确认的好友请求列表项 * Pending friend request item with accept/reject buttons */ @Composable fun PendingFriendRequestItem( contact: Contact, onAccept: () -> Unit, onReject: () -> Unit ) { val surfaceColor = MaterialTheme.colorScheme.surface
Row( modifier = Modifier .fillMaxWidth() .background(surfaceColor) .padding(horizontal = 16.dp, vertical = 12.dp), verticalAlignment = Alignment.CenterVertically ) { // 头像 val avatarModifier = Modifier .size(52.dp) .clip(CircleShape)
if (contact.contactAvatarUrl.isNotBlank()) { AsyncImage( model = contact.contactAvatarUrl, contentDescription = "${contact.contactName} avatar", modifier = avatarModifier, contentScale = ContentScale.Crop ) } else { Box( modifier = avatarModifier.background(PrimaryBlue), contentAlignment = Alignment.Center ) { Text( text = contact.contactName.firstOrNull()?.uppercase() ?: "?", fontSize = 20.sp, fontWeight = FontWeight.Medium, color = Color.White ) } }
Spacer(modifier = Modifier.width(12.dp))
// 联系人信息 Column( modifier = Modifier.weight(1f) ) { Text( text = contact.contactName, fontSize = 16.sp, fontWeight = FontWeight.Medium, color = primaryTextColor() ) Text( text = "Wants to be your friend", fontSize = 13.sp, color = secondaryTextColor() ) }
Spacer(modifier = Modifier.width(8.dp))
// Accept 按钮 Button( onClick = onAccept, colors = ButtonDefaults.buttonColors( containerColor = PrimaryBlue ), shape = RoundedCornerShape(6.dp), contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp), modifier = Modifier.height(36.dp) ) { Text( text = stringResource(R.string.action_accept), fontSize = 13.sp, color = Color.White ) }
Spacer(modifier = Modifier.width(8.dp))
// Reject 按钮 OutlinedButton( onClick = onReject, colors = ButtonDefaults.outlinedButtonColors( contentColor = Color(0xFF6B7280) ), border = BorderStroke(1.dp, Color(0xFFD1D5DB)), shape = RoundedCornerShape(6.dp), contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp), modifier = Modifier.height(36.dp) ) { Text( text = stringResource(R.string.action_reject), fontSize = 13.sp ) } } }
/** * 联系人列表项 * Contact list item */ @Composable fun ContactListItem( contact: Contact, viewModel: ContactsViewModel, onClick: () -> Unit, onAvatarClick: (Contact) -> Unit = {} ) { // 监听 conversationCache 的变化，确保 GROUP 信息加载后界面会更新 val conversationCache by viewModel.conversationCache.collectAsStateWithLifecycle() val pinnedConversationIds by viewModel.pinnedConversationIds.collectAsStateWithLifecycle()
// 使用 ViewModel 的方法获取显示名称和头像（对 GROUP 会从 Conversation 中获取） val displayName = viewModel.getDisplayName(contact) val avatarUrl = viewModel.getAvatarUrl(contact)
// 调试日志 Log.d("ContactListItem", "Contact ID: ${contact.contactId}") Log.d("ContactListItem", "Contact Type: ${contact.type}") Log.d("ContactListItem", "Conversation ID: ${contact.conversationId}") Log.d("ContactListItem", "Display Name: $displayName") Log.d("ContactListItem", "Avatar URL: $avatarUrl") Log.d("ContactListItem", "ConversationCache size: ${conversationCache.size}")
val surfaceColor = MaterialTheme.colorScheme.surface
Row( modifier = Modifier .fillMaxWidth() .clickable(onClick = onClick) .background(surfaceColor) .padding(horizontal = 16.dp, vertical = 12.dp), verticalAlignment = Alignment.CenterVertically ) { // 头像 val avatarModifier = Modifier .size(52.dp) .clip(CircleShape) .clickable { onAvatarClick(contact) }
if (avatarUrl.isNotBlank()) { Log.d("ContactListItem", "Loading image for $displayName: $avatarUrl") AsyncImage( model = avatarUrl, contentDescription = "$displayName avatar", modifier = avatarModifier, contentScale = ContentScale.Crop, onError = { error -> Log.e("ContactListItem", "Failed to load image for $displayName: ${error.result.throwable}") }, onSuccess = { Log.d("ContactListItem", "Successfully loaded image for $displayName") } ) } else { // 没有头像URL时显示首字母 Log.d("ContactListItem", "No avatarUrl for $displayName, showing initials") Box( modifier = avatarModifier.background(if (contact.isGroup()) Color(0xFFFF9800) else PrimaryBlue), contentAlignment = Alignment.Center ) { Text( text = displayName.firstOrNull()?.uppercase() ?: "?", fontSize = 20.sp, fontWeight = FontWeight.Medium, color = Color.White ) } }
Spacer(modifier = Modifier.width(12.dp))
// 联系人信息 Column( modifier = Modifier.weight(1f) ) { Row( verticalAlignment = Alignment.CenterVertically ) { Text( text = displayName, fontSize = 16.sp, fontWeight = FontWeight.Medium, color = primaryTextColor(), maxLines = 1, overflow = TextOverflow.Ellipsis )
// 群组图标 if (contact.isGroup()) { Spacer(modifier = Modifier.width(4.dp)) Icon( imageVector = Icons.Filled.People, contentDescription = stringResource(R.string.content_description_group), tint = secondaryTextColor(), modifier = Modifier.size(16.dp) ) } }
// 显示原始姓名（如果设置了备注） if (contact.alias.isNotBlank()) { val originalName = contact.contactName.ifBlank { stringResource(R.string.contacts_original_name_unknown) } Text( text = stringResource(R.string.contacts_original_name_label, originalName), fontSize = 13.sp, color = secondaryTextColor(), maxLines = 1, overflow = TextOverflow.Ellipsis ) } }
// 收藏图标 val isPinned = contact.conversationId.isNotBlank() && pinnedConversationIds.contains(contact.conversationId) if (contact.isFavorite || isPinned) { Icon( imageVector = Icons.Filled.Star, contentDescription = stringResource(R.string.content_description_favorite), tint = Color(0xFFFFC107), modifier = Modifier.size(20.dp) ) } } }
/** * 个人设置页面（包含退出登录） * Profile settings screen (Includes logout) */ @OptIn(ExperimentalLayoutApi::class) @Composable fun ProfileScreen( onLogout: () -> Unit, onLanguageClick: () -> Unit, onPrivacyClick: () -> Unit, onAboutClick: () -> Unit, onProfileClick: () -> Unit, themeOption: ThemeOption, onThemeSelected: (ThemeOption) -> Unit, profileState: ProfileSettingsUiState ) { val backgroundColor = MaterialTheme.colorScheme.background val surfaceColor = MaterialTheme.colorScheme.surface val cardColor = MaterialTheme.colorScheme.surfaceVariant val dividerColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.15f) val displayName = if (profileState.displayName.isNotBlank()) { profileState.displayName } else { stringResource(R.string.profile_placeholder_name) } val email = if (profileState.email.isNotBlank()) { profileState.email } else { stringResource(R.string.profile_placeholder_email) } val scrollState = rememberScrollState()
Column( modifier = Modifier .fillMaxSize() .background(backgroundColor) .verticalScroll(scrollState) ) { // 用户信息卡片 val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f val headerElevation = if (isDark) 10.dp else 4.dp Surface( modifier = Modifier .fillMaxWidth() .padding(16.dp), color = surfaceColor, shadowElevation = headerElevation, tonalElevation = if (isDark) 6.dp else 0.dp, shape = RoundedCornerShape(12.dp) ) { val highlightColor = if (isDark) MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.85f) else surfaceColor Box( modifier = Modifier .shadow(if (isDark) 12.dp else 4.dp, RoundedCornerShape(12.dp), clip = false) .border( width = 1.dp, color = if (isDark) MaterialTheme.colorScheme.outline.copy(alpha = 0.3f) else Color.Transparent, shape = RoundedCornerShape(12.dp) ) .clip(RoundedCornerShape(12.dp)) .background(highlightColor) .clickable(onClick = onProfileClick) .padding(16.dp) ) { Row( verticalAlignment = Alignment.CenterVertically ) { // 头像 Box( modifier = Modifier .size(64.dp) .clip(CircleShape) .background(PrimaryBlue), contentAlignment = Alignment.Center ) { if (profileState.avatarUrl.isNotBlank()) { AsyncImage( model = profileState.avatarUrl, contentDescription = stringResource(R.string.profile_edit_avatar_content_description), contentScale = ContentScale.Crop, modifier = Modifier.fillMaxSize() ) } else { Icon( imageVector = Icons.Filled.Person, contentDescription = null, tint = Color.White, modifier = Modifier.size(32.dp) ) } }
Spacer(modifier = Modifier.width(16.dp))
Column( modifier = Modifier.weight(1f) ) { Text( text = displayName, fontSize = 18.sp, fontWeight = FontWeight.Medium, color = primaryTextColor() ) Spacer(modifier = Modifier.height(4.dp)) Text( text = email, fontSize = 14.sp, color = secondaryTextColor() ) }
Icon( imageVector = Icons.Filled.ChevronRight, contentDescription = null, tint = secondaryTextColor() ) } } }
Spacer(modifier = Modifier.height(8.dp))
// 设置项列表 Surface( modifier = Modifier.fillMaxWidth(), color = surfaceColor ) { Column { SettingItem( icon = Icons.Filled.Notifications, title = stringResource(R.string.settings_notifications), subtitle = stringResource(R.string.settings_notifications_subtitle), onClick = { } ) HorizontalDivider( modifier = Modifier.padding(start = 56.dp), thickness = 0.5.dp, color = dividerColor ) SettingItem( icon = Icons.Filled.Lock, title = stringResource(R.string.settings_privacy), onClick = onPrivacyClick ) HorizontalDivider( modifier = Modifier.padding(start = 56.dp), thickness = 0.5.dp, color = dividerColor ) SettingItem( icon = Icons.Filled.Language, title = stringResource(R.string.settings_language), onClick = onLanguageClick ) HorizontalDivider( modifier = Modifier.padding(start = 56.dp), thickness = 0.5.dp, color = dividerColor ) SettingItem( icon = Icons.Filled.Info, title = stringResource(R.string.settings_about), onClick = onAboutClick ) } }
Spacer(modifier = Modifier.height(16.dp))
Card( modifier = Modifier .fillMaxWidth() .padding(horizontal = 16.dp), colors = CardDefaults.cardColors(containerColor = cardColor), shape = RoundedCornerShape(16.dp) ) { Column( modifier = Modifier .fillMaxWidth() .padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp) ) { Text( text = stringResource(R.string.theme_section_title), style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold ) Text( text = stringResource(R.string.theme_section_description), style = MaterialTheme.typography.bodySmall, color = secondaryTextColor() ) FlowRow( horizontalArrangement = Arrangement.spacedBy(12.dp), verticalArrangement = Arrangement.spacedBy(12.dp) ) { ThemeOption.entries.forEach { option -> val chipBorder = FilterChipDefaults.filterChipBorder( enabled = true, selected = option == themeOption, borderColor = MaterialTheme.colorScheme.outline, selectedBorderColor = MaterialTheme.colorScheme.primary ) FilterChip( selected = option == themeOption, onClick = { onThemeSelected(option) }, label = { Text(text = stringResource(option.labelRes)) }, border = chipBorder, leadingIcon = if (option == themeOption) { { Icon( imageVector = Icons.Filled.Check, contentDescription = null, tint = MaterialTheme.colorScheme.primary ) } } else null ) } } } }
Spacer(modifier = Modifier.weight(1f))
// 退出登录按钮 Button( onClick = onLogout, modifier = Modifier .fillMaxWidth() .padding(16.dp), colors = ButtonDefaults.buttonColors( containerColor = UnreadBadgeRed ), shape = RoundedCornerShape(8.dp) ) { Icon( imageVector = Icons.AutoMirrored.Filled.Logout, contentDescription = null, tint = MaterialTheme.colorScheme.onPrimary, modifier = Modifier.size(20.dp) ) Spacer(modifier = Modifier.width(8.dp)) Text( text = stringResource(R.string.home_logout), fontSize = 16.sp ) } // End Button } // End Column (ProfileScreen main content) } // End ProfileScreen function
/** * 设置项组件 * Setting item component */ @Composable fun SettingItem( icon: ImageVector, title: String, subtitle: String? = null, onClick: () -> Unit ) { Row( modifier = Modifier .fillMaxWidth() .clickable(onClick = onClick) .padding(horizontal = 16.dp, vertical = 16.dp), verticalAlignment = Alignment.CenterVertically ) { Icon( imageVector = icon, contentDescription = null, tint = secondaryTextColor(), modifier = Modifier.size(24.dp) ) Spacer(modifier = Modifier.width(16.dp)) Column(modifier = Modifier.weight(1f)) { Text( text = title, fontSize = 16.sp, color = primaryTextColor() ) subtitle?.let { Spacer(modifier = Modifier.height(2.dp)) Text( text = it, fontSize = 13.sp, color = secondaryTextColor() ) } } Icon( imageVector = Icons.Filled.ChevronRight, contentDescription = null, tint = secondaryTextColor() ) } }
/** * 添加好友弹窗 * Add Friend Dialog */ @OptIn(ExperimentalMaterial3Api::class) @Composable fun AddFriendDialog( homeViewModel: HomeViewModel, onDismiss: () -> Unit ) { val searchQuery by homeViewModel.addFriendSearchQuery.collectAsStateWithLifecycle() val searchResults by homeViewModel.addFriendSearchResults.collectAsStateWithLifecycle() val groupSearchResults by homeViewModel.addGroupSearchResults.collectAsStateWithLifecycle() val isSearching by homeViewModel.isAddFriendSearching.collectAsStateWithLifecycle()
// 观察 allContacts 的变化，确保联系人状态更新时 UI 会重新组合 val allContacts by homeViewModel.allContacts.collectAsStateWithLifecycle()
val context = LocalContext.current
// 当对话框打开时，强制刷新联系人列表以确保数据最新 LaunchedEffect(Unit) { Log.d("AddFriendDialog", "Dialog opened, refreshing contacts...") homeViewModel.refreshContacts() }
Dialog( onDismissRequest = onDismiss, properties = DialogProperties( dismissOnBackPress = true, dismissOnClickOutside = true, usePlatformDefaultWidth = false ) ) { Card( modifier = Modifier .fillMaxWidth(0.9f) .fillMaxHeight(0.7f), shape = RoundedCornerShape(16.dp), colors = CardDefaults.cardColors( containerColor = MaterialTheme.colorScheme.surface ), elevation = CardDefaults.cardElevation(defaultElevation = 8.dp) ) { Column( modifier = Modifier.fillMaxSize() ) { // 顶部标题栏 Row( modifier = Modifier .fillMaxWidth() .padding(16.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Text( text = stringResource(R.string.add_friend_title), fontSize = 20.sp, fontWeight = FontWeight.Bold, color = primaryTextColor() ) IconButton( onClick = onDismiss, modifier = Modifier.size(32.dp) ) { Icon( imageVector = Icons.Filled.Close, contentDescription = stringResource(R.string.content_description_close), tint = secondaryTextColor() ) } }
HorizontalDivider( thickness = 1.dp, color = MaterialTheme.colorScheme.outlineVariant )
// 搜索栏 OutlinedTextField( value = searchQuery, onValueChange = { homeViewModel.searchUsersAndGroupsForAdd(it) }, modifier = Modifier .fillMaxWidth() .padding(16.dp), placeholder = { Text( text = stringResource(R.string.add_friend_search_placeholder), color = secondaryTextColor() ) }, leadingIcon = { Icon( imageVector = Icons.Filled.Search, contentDescription = stringResource(R.string.content_description_search), tint = secondaryTextColor() ) }, trailingIcon = { if (searchQuery.isNotEmpty()) { IconButton( onClick = { homeViewModel.clearAddFriendSearch() } ) { Icon( imageVector = Icons.Filled.Clear, contentDescription = stringResource(R.string.content_description_close), tint = secondaryTextColor() ) } } }, singleLine = true, colors = OutlinedTextFieldDefaults.colors( focusedBorderColor = PrimaryBlue, unfocusedBorderColor = MaterialTheme.colorScheme.outlineVariant, cursorColor = PrimaryBlue, focusedTextColor = primaryTextColor(), unfocusedTextColor = primaryTextColor(), focusedContainerColor = MaterialTheme.colorScheme.surface, unfocusedContainerColor = MaterialTheme.colorScheme.surface, focusedLeadingIconColor = secondaryTextColor(), unfocusedLeadingIconColor = secondaryTextColor(), focusedTrailingIconColor = secondaryTextColor(), unfocusedTrailingIconColor = secondaryTextColor(), focusedPlaceholderColor = secondaryTextColor(), unfocusedPlaceholderColor = secondaryTextColor() ), shape = RoundedCornerShape(12.dp) )
// 搜索结果区域 Box( modifier = Modifier .fillMaxWidth() .weight(1f) ) { when { // 加载中状态 isSearching -> { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { CircularProgressIndicator( color = PrimaryBlue, modifier = Modifier.size(40.dp) ) } } // 空搜索状态 searchQuery.isEmpty() -> { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { Column( horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp) ) { Icon( imageVector = Icons.Filled.PersonSearch, contentDescription = null, modifier = Modifier.size(64.dp), tint = secondaryTextColor() ) Text( text = stringResource(R.string.add_friend_search_hint), color = secondaryTextColor(), fontSize = 16.sp ) Text( text = stringResource(R.string.add_friend_search_subtitle), color = secondaryTextColor(), fontSize = 14.sp ) } } } // 无结果状态 searchResults.isEmpty() && groupSearchResults.isEmpty() -> { Box( modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center ) { Column( horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp) ) { Icon( imageVector = Icons.Filled.SearchOff, contentDescription = null, modifier = Modifier.size(64.dp), tint = secondaryTextColor() ) Text( text = stringResource(R.string.no_results_found), color = primaryTextColor(), fontSize = 16.sp, fontWeight = FontWeight.Medium ) Text( text = stringResource(R.string.try_different_search_keyword), color = secondaryTextColor(), fontSize = 14.sp ) } } } // 显示搜索结果 else -> { LazyColumn( modifier = Modifier.fillMaxSize(), contentPadding = PaddingValues(vertical = 8.dp) ) { // 群组搜索结果 if (groupSearchResults.isNotEmpty()) { item { Text( text = stringResource(R.string.group_search_section), fontSize = 14.sp, fontWeight = FontWeight.Bold, color = secondaryTextColor(), modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp) ) } items( items = groupSearchResults, key = { "group_${it.id}" } ) { group -> GroupSearchResultItem( group = group, onJoinClick = { Log.d("AddFriendDialog", "Join group: ${group.name} (${group.id})") homeViewModel.joinGroup( groupId = group.id, onSuccess = { android.widget.Toast.makeText( context, context.getString(R.string.group_join_success), android.widget.Toast.LENGTH_SHORT ).show() }, onError = { error -> android.widget.Toast.makeText( context, context.getString(R.string.group_join_failed) + ": $error", android.widget.Toast.LENGTH_SHORT ).show() } ) } ) } }
// 用户搜索结果 if (searchResults.isNotEmpty()) { item { Text( text = stringResource(R.string.section_contacts), fontSize = 14.sp, fontWeight = FontWeight.Bold, color = secondaryTextColor(), modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp) ) } items( items = searchResults, key = { "user_${it.id}" } ) { user -> // 观察 allContacts 的变化，确保联系人状态更新时按钮会更新 // allContacts 是 State，当它变化时会触发重新组合 val contactStatus = remember(allContacts, user.id) { homeViewModel.getContactStatus(user.id) }
UserSearchResultItem( user = user, contactStatus = contactStatus, onAddClick = { // 发送好友请求 Log.d("AddFriendDialog", "Send friend request to: ${user.username} (${user.id})") homeViewModel.sendFriendRequest(user) } ) } } } } } } } } } }
/** * 群组搜索结果项 * Group Search Result Item */ @Composable fun GroupSearchResultItem( group: com.example.cs501_micro_chat.data.model.Group, onJoinClick: () -> Unit ) { Row( modifier = Modifier .fillMaxWidth() .padding(horizontal = 16.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically ) { // 群组头像 if (group.avatarUrl.isNotBlank()) { AsyncImage( model = group.avatarUrl, contentDescription = stringResource(R.string.content_description_group), modifier = Modifier .size(48.dp) .clip(CircleShape), contentScale = ContentScale.Crop ) } else { Box( modifier = Modifier .size(48.dp) .clip(CircleShape) .background(PrimaryBlue), contentAlignment = Alignment.Center ) { Icon( imageVector = Icons.Filled.Group, contentDescription = stringResource(R.string.content_description_group), tint = Color.White, modifier = Modifier.size(24.dp) ) } }
Spacer(modifier = Modifier.width(12.dp))
// 群组信息 Column( modifier = Modifier.weight(1f) ) { Text( text = group.name, fontSize = 16.sp, fontWeight = FontWeight.Medium, color = primaryTextColor() ) Text( text = stringResource(R.string.group_members_count, group.memberIds.size), fontSize = 12.sp, color = secondaryTextColor() ) }
Spacer(modifier = Modifier.width(8.dp))
// 加入按钮 Button( onClick = onJoinClick, colors = ButtonDefaults.buttonColors( containerColor = PrimaryBlue, contentColor = Color.White ), shape = RoundedCornerShape(8.dp), contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp) ) { Icon( imageVector = Icons.Filled.Add, contentDescription = null, modifier = Modifier.size(18.dp) ) Spacer(modifier = Modifier.width(4.dp)) Text( text = stringResource(R.string.group_join_button), fontSize = 14.sp ) } } }
