@Composable
fun GroupProfileScreen(
    conversationId: String,
    onBack: () -> Unit,
    onStartChat: (conversationId: String, name: String, avatarUrl: String) -> Unit,
    onLeftGroup: () -> Unit,
    onOpenSearch: (conversationId: String) -> Unit,
    onMemberClick: (String) -> Unit = {},
    onRefreshContacts: () -> Unit = {},
    viewModel: GroupProfileViewModel = hiltViewModel()
) {
    LaunchedEffect(conversationId) {
        viewModel.loadGroup(conversationId)
    }

    val state by viewModel.uiState.collectAsStateWithLifecycle()
    val snackbarHostState = remember { SnackbarHostState() }
    val context = LocalContext.current
    var snackbarStyle by remember { mutableStateOf(GroupSnackbarStyle.INFO) }

    LaunchedEffect(Unit) {
        viewModel.events.collect { event ->
            when (event) {
                is GroupProfileEvent.OpenChat -> onStartChat(event.conversationId, event.name, event.avatarUrl)
                GroupProfileEvent.LeftGroup -> onLeftGroup()
                GroupProfileEvent.GroupDismissed -> {
                    snackbarStyle = GroupSnackbarStyle.SUCCESS
                    snackbarHostState.showSnackbar(context.getString(R.string.group_profile_dismissed_success))
                    onLeftGroup() // 解散后也返回上一页
                }
                is GroupProfileEvent.SearchHistory -> onOpenSearch(event.conversationId)
                is GroupProfileEvent.ShowMessage -> {
                    snackbarStyle = GroupSnackbarStyle.ERROR
                    val text = event.messageRes?.let { context.getString(it) } ?: event.message.orEmpty()
                    snackbarHostState.showSnackbar(text)
                }
                is GroupProfileEvent.ShowStatus -> {
                    snackbarStyle = if (event.success) GroupSnackbarStyle.SUCCESS else GroupSnackbarStyle.ERROR
                    snackbarHostState.showSnackbar(context.getString(event.messageRes))
                }
                is GroupProfileEvent.PinStatusChanged -> {
                    snackbarStyle = GroupSnackbarStyle.SUCCESS
                    snackbarHostState.showSnackbar(
                        if (event.isPinned) {
                            context.getString(R.string.group_profile_pin_enabled)
                        } else {
                            context.getString(R.string.group_profile_pin_disabled)
                        }
                    )
                }
                is GroupProfileEvent.Renamed -> onRefreshContacts()
            }
        }
    }

    Scaffold(
        containerColor = MaterialTheme.colorScheme.background,
        snackbarHost = {
            SnackbarHost(snackbarHostState) { data ->
                GroupColoredSnackbar(data = data, style = snackbarStyle)
            }
        }
    ) { paddingValues ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .verticalScroll(rememberScrollState()),
            contentAlignment = Alignment.TopCenter
        ) {
            if (state.isLoading) {
                CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
            } else {
                val openChat: () -> Unit = {
                    val conversationId = state.conversationId
                    if (conversationId.isNotBlank()) {
                        onStartChat(conversationId, state.name, state.avatarUrl)
                    } else {
                        viewModel.startChat()
                    }
                }
                var showClearHistoryDialog by remember { mutableStateOf(false) }
                var showDismissGroupDialog by remember { mutableStateOf(false) }

                GroupProfileContent(
                    state = state,
                    onNameChange = viewModel::onNameChange,
                    onSaveName = viewModel::saveName,
                    onStartChat = openChat,
                    onSearchHistory = viewModel::searchHistory,
                    onTogglePinned = viewModel::togglePinned,
                    onClearHistory = { showClearHistoryDialog = true },
                    onLeaveGroup = viewModel::leaveGroup,
                    onDismissGroup = { showDismissGroupDialog = true },
                    onMemberClick = onMemberClick
                )

                if (showClearHistoryDialog) {
                    ConfirmDialog(
                        title = stringResource(R.string.clear_history_title),
                        description = stringResource(R.string.clear_history_description),
                        confirmText = stringResource(R.string.clear_history_confirm),
                        cancelText = stringResource(R.string.user_profile_delete_confirm_cancel),
                        onConfirm = {
                            showClearHistoryDialog = false
                            viewModel.clearHistory()
                        },
                        onDismiss = { showClearHistoryDialog = false }
                    )
                }

                if (showDismissGroupDialog) {
                    ConfirmDialog(
                        title = stringResource(R.string.group_profile_dismiss_title),
                        description = stringResource(R.string.group_profile_dismiss_description),
                        confirmText = stringResource(R.string.group_profile_dismiss_confirm),
                        cancelText = stringResource(R.string.user_profile_delete_confirm_cancel),
                        onConfirm = {
                            showDismissGroupDialog = false
                            viewModel.dismissGroup()
                        },
                        onDismiss = { showDismissGroupDialog = false }
                    )
                }
            }
        }
    }
}

@Composable
private fun GroupProfileContent(
    state: GroupProfileUiState,
    onNameChange: (String) -> Unit,
    onSaveName: () -> Unit,
    onStartChat: () -> Unit,
    onSearchHistory: () -> Unit,
    onTogglePinned: () -> Unit,
    onClearHistory: () -> Unit,
    onLeaveGroup: () -> Unit,
    onDismissGroup: () -> Unit,
    onMemberClick: (String) -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 12.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            tonalElevation = 2.dp
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                if (state.avatarUrl.isNotBlank()) {
                    AsyncImage(
                        model = state.avatarUrl,
                        contentDescription = null,
                        modifier = Modifier
                            .size(96.dp)
                            .clip(CircleShape),
                        contentScale = ContentScale.Crop
                    )
                } else {
                    Icon(
                        imageVector = Icons.Filled.Group,
                        contentDescription = null,
                        modifier = Modifier.size(64.dp),
                        tint = MaterialTheme.colorScheme.primary
                    )
                }

                OutlinedTextField(
                    value = state.name,
                    onValueChange = onNameChange,
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text(text = stringResource(R.string.group_profile_name_label)) },
                    singleLine = true,
                    trailingIcon = {
                        if (state.isSaving) {
                            CircularProgressIndicator(
                                modifier = Modifier.size(16.dp),
                                strokeWidth = 2.dp
                            )
                        } else {
                            IconButton(onClick = onSaveName, enabled = state.name.isNotBlank()) {
                                Icon(
                                    imageVector = Icons.Filled.Check,
                                    contentDescription = stringResource(R.string.group_profile_save_name)
                                )
                            }
                        }
                    }
                )
            }
        }

        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            tonalElevation = 1.dp
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = stringResource(R.string.group_profile_members_title),
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.SemiBold
                )
                FlowMembers(members = state.members, onMemberClick = onMemberClick)
            }
        }

        PinSettingRow(
            title = stringResource(R.string.group_profile_pin_title),
            description = when {
                !state.canPin -> stringResource(R.string.group_profile_pin_unavailable)
                state.isPinned -> stringResource(R.string.group_profile_pin_on_description)
                else -> stringResource(R.string.group_profile_pin_off_description)
            },
            isPinned = state.isPinned,
            enabled = state.canPin && !state.isRemoved,
            isLoading = state.isPinUpdating,
            onToggle = onTogglePinned
        )

        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            tonalElevation = 1.dp
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                ActionButton(
                    icon = Icons.AutoMirrored.Filled.Send,
                    label = stringResource(R.string.user_profile_send_message),
                    onClick = onStartChat,
                    enabled = !state.isRemoved
                )
                ActionButton(
                    icon = Icons.Filled.Search,
                    label = stringResource(R.string.user_profile_search_history),
                    onClick = onSearchHistory,
                    enabled = !state.isRemoved && state.conversationId.isNotBlank()
                )
                ActionButton(
                    icon = Icons.Outlined.Clear,
                    label = stringResource(R.string.user_profile_clear_history),
                    onClick = onClearHistory,
                    enabled = !state.isRemoved && state.conversationId.isNotBlank(),
                    containerColor = MaterialTheme.colorScheme.surfaceVariant
                )

                // 如果是群主，显示解散群组按钮；否则显示退出群组按钮
                if (state.isOwner) {
                    ActionButton(
                        icon = Icons.Filled.Delete,
                        label = if (state.isDismissing)
                            stringResource(R.string.group_profile_dismissing)
                        else
                            stringResource(R.string.group_profile_dismiss),
                        onClick = onDismissGroup,
                        enabled = !state.isDismissing && !state.isRemoved,
                        containerColor = Color(0xFFDC2626)
                    )
                } else {
                    ActionButton(
                        icon = Icons.Filled.Delete,
                        label = if (state.isLeaving)
                            stringResource(R.string.group_profile_leaving)
                        else
                            stringResource(R.string.group_profile_leave),
                        onClick = onLeaveGroup,
                        enabled = !state.isLeaving && !state.isRemoved,
                        containerColor = Color(0xFFEF4444)
                    )
                }
            }
        }
    }
}

